/* Déclic — Anglais B1 (unités 7 à 9). Format : docs/ANGLAIS.md */
(()=>{
// X('a','b',['c','d']) → toutes les combinaisons de morceaux, séparés par une espace (réponses acceptées)
const X=(...ps)=>ps.reduce((acc,p)=>acc.flatMap(a=>[].concat(p).map(b=>(a+' '+b).replace(/\s+/g,' ').trim())),['']);
COURS.push(
{subj:'en', sem:'b1', id:'en-b1-media', o:7, h:'News and media', p:'Comprendre et raconter l’actualité : la voix passive à tous les temps, le vocabulaire de l’information et la langue particulière des titres de presse.', steps:[
 {kind:'Écoute', h:'Did you see the news?',
  p:`<p>By the end of this unit, you will be able to understand and tell a news story, use the passive at different tenses and read newspaper headlines.</p>
<p>Maya and Josh are having breakfast. Maya is reading the news on her phone. <b>Listen without reading</b>, twice if you need to, then answer. The script will appear after your answer.</p>
<p><b>Question:</b> where was the stolen painting found?</p>`,
  audio:[['Maya','Josh, listen to this. You know the painting that was stolen from the city museum last spring?'],['Josh','The small landscape? The one that’s worth millions?'],['Maya','That’s the one. It’s been found!'],['Josh','No way! Where?'],['Maya','In a garage in Bristol, of all places. It was wrapped in an old blanket behind some paint tins. According to the article, the police were contacted by a neighbour who had noticed people coming and going at night.'],['Josh','Has anyone been arrested?'],['Maya','Two men were arrested yesterday, and they’re being questioned at the moment. Apparently, the painting hasn’t been damaged at all.'],['Josh','That’s lucky. So when will it be back in the museum?'],['Maya','It has to be checked by experts first, but it should be put back on display before Christmas.'],['Josh','Let’s go and see it when it’s back. I’ve never even seen it.']], cache:true,
  opts:['In a museum in Bristol','In a garage in Bristol','In a neighbour’s flat','In an expert’s office'], ans:1,
  why:'<i lang="en">In a garage in Bristol… wrapped in an old blanket</i> : dans un garage à Bristol, enveloppé dans une vieille couverture. Remarque toutes les formes passives du dialogue : <i lang="en">was stolen, has been found, were arrested, are being questioned, has to be checked</i>. C’est le sujet de l’unité.'},

 {kind:'Vocabulaire', h:'Talking about the news',
  p:`<p>Here are useful words and chunks for talking about the news. Tap a line to hear it, then say it aloud. These words go into your <b>vocabulary review</b>.</p>`,
  mots:[['the news','les informations, les nouvelles','The news is on at six.'],['a news story','un sujet d’actualité, une nouvelle','It was the main news story of the day.'],['a headline','un titre (de journal)','I only had time to read the headlines.'],['to make the headlines','faire la une','The story made the headlines all over the world.'],['breaking news','information de dernière minute','We interrupt this programme for some breaking news.'],['a reporter / a journalist','un ou une journaliste','A reporter was sent to the scene.'],['to report on something','faire un reportage sur, rendre compte de','She reports on climate issues for a local paper.'],['according to…','selon…, d’après…','According to the police, nobody was hurt.'],['a source','une source','The information was confirmed by two sources.'],['to go viral','devenir viral, faire le buzz','The video went viral in a few hours.'],['fake news','les fausses informations, les infox','Fake news often spreads faster than real news.'],['an eyewitness / a witness','un témoin (oculaire)','An eyewitness said the car was going very fast.'],['a press conference','une conférence de presse','The minister will hold a press conference at noon.'],['to release a statement','publier un communiqué','The company released a statement this morning.']],
  note:'<b>Pièges :</b> <i lang="en">news</i> est <b>indénombrable</b> et singulier, malgré son -s : <i lang="en">The news <b>is</b> good</i>, jamais « a news » (on dit <i lang="en">a piece of news</i> ou <i lang="en">a news story</i>). Et <i lang="en">actually</i> veut dire « en fait » : « actuellement » se dit <i lang="en">currently</i> ou <i lang="en">at the moment</i>.'},

 {kind:'Pratique', h:'Your turn: the headlines',
  p:`<p>Translate the sentence into English, using a chunk from the list.</p><p><b>Question:</b> « Cette histoire a fait la une dans le monde entier. »</p>`, lab:'Your sentence',
  txt:X(['This story','The story','That story'],['made the headlines','made headlines','hit the headlines','was front-page news'],['all over the world','around the world','across the world','worldwide','throughout the world']),
  why:'<i lang="en">This story made the headlines all over the world.</i> « faire la une » = <i lang="en">to make the headlines</i> (ou <i lang="en">to hit the headlines</i>). Le passé composé français devient ici un prétérit, car l’événement est terminé.'},

 {kind:'Grammaire', h:'The passive: form and use',
  p:`<p>Dans le dialogue, Maya dit <i lang="en">The painting <b>was stolen</b></i>, <i lang="en">It <b>has been found</b></i>, <i lang="en">Two men <b>were arrested</b></i>. Elle ne dit pas qui a volé ni qui a arrêté : on ne le sait pas, ou c’est évident (la police), et ce qui compte, c’est le tableau. C’est le rôle de la <b>voix passive</b>.</p>
<div class="def"><p><b>Passif = be conjugué + participe passé</b> (la 3e colonne des verbes irréguliers : <i lang="en">stolen, found, written</i> ; <i lang="en">-ed</i> pour les réguliers). C’est <b>be</b> qui porte le temps ; le participe ne change jamais. L’auteur de l’action, s’il est utile, est introduit par <b>by</b>.</p></div>
<div class="idea"><p>À l’actif, le sujet est celui qui agit : <i lang="en">Someone stole the painting.</i> Au passif, le sujet est ce qui subit l’action : <i lang="en">The painting was stolen.</i> On choisit le passif quand l’auteur est <b>inconnu</b>, <b>évident</b> ou <b>moins important</b> que l’action. C’est pourquoi il est partout dans les informations, les règlements, les textes techniques et scientifiques. On n’ajoute <i lang="en">by…</i> que si l’information est intéressante : <i lang="en">The song was written <b>by a 15-year-old girl</b>.</i></p></div>
<div class="ex"><p><i lang="en">Someone stole the painting last spring.</i> → <i lang="en">The painting <b>was stolen</b> last spring.</i><br><i lang="en">The police arrested two men.</i> → <i lang="en">Two men <b>were arrested</b>.</i> (<i lang="en">by the police</i> est inutile : qui d’autre&nbsp;?)</p></div>
<div class="warn"><p><b>Pièges des francophones.</b> L’anglais n’a pas de « on » : <i lang="en">on a retrouvé le tableau</i> se dit très souvent au passif, <i lang="en">The painting has been found</i>. Avec les verbes à deux compléments (<i lang="en">give, offer, tell, send, ask, show</i>), c’est la <b>personne</b> qui devient sujet : « on m’a dit » = <b>I was told</b>, « on m’a proposé un poste » = <b>I was offered a job</b> (jamais « It was told to me »). Et « je suis né » est un passif en anglais : <b>I was born</b> (pas « I am born »).</p></div>`,
  audio:'The painting was stolen last spring. Two men were arrested. The song was written by a fifteen-year-old girl. I was born in Geneva. I was offered a job in London.'},

 {kind:'Grammaire', h:'The passive at every tense',
  p:`<p>Pour mettre une phrase au passif, il suffit de savoir conjuguer <b>be</b> à tous les temps. Le participe passé reste le même partout.</p>
<div class="def"><ul><li>Présent simple : <b>am / is / are + participe</b> : <i lang="en">English <b>is spoken</b> here.</i></li><li>Présent continu : <b>am / is / are being + participe</b> : <i lang="en">The bridge <b>is being repaired</b>.</i> (en ce moment)</li><li>Prétérit : <b>was / were + participe</b> : <i lang="en">The museum <b>was built</b> in 1890.</i></li><li>Present perfect : <b>has / have been + participe</b> : <i lang="en">The painting <b>has been found</b>.</i></li><li>Futur : <b>will be + participe</b> : <i lang="en">The results <b>will be announced</b> on Monday.</i></li><li>Modaux : <b>can / must / should / might / has to + be + participe</b> : <i lang="en">Tickets <b>can be bought</b> online.</i></li></ul></div>
<div class="idea"><p>Pour choisir le temps, demande-toi quel temps aurait le verbe à l’actif, et mets <i lang="en">be</i> à ce temps-là : <i lang="en">They <b>are repairing</b> the bridge</i> (présent continu) → <i lang="en">The bridge <b>is being</b> repaired</i>. Questions et négations suivent les règles de <i lang="en">be</i>, de <i lang="en">have</i> ou du modal, sans <i lang="en">do</i> : <i lang="en">Was anyone hurt? Has the thief been caught? It wasn’t damaged.</i></p></div>
<div class="ex"><p><i lang="en">They will open the new station in May.</i> → <i lang="en">The new station <b>will be opened</b> in May.</i><br><i lang="en">You must switch off your phone.</i> → <i lang="en">Phones <b>must be switched off</b>.</i></p></div>
<div class="warn"><p>Le passé composé français a deux traductions. Avec un moment précis, c’est le prétérit : <i lang="en">Il a été retrouvé hier</i> = <i lang="en">It <b>was found</b> yesterday</i>. Pour une nouvelle sans date, c’est le present perfect : <i lang="en">It <b>has been found</b>!</i> Et n’oublie jamais <i lang="en">be</i> : « The painting found » n’est correct que dans un titre de journal. Après <i lang="en">be</i>, toujours le participe : <i lang="en">must be <b>done</b></i>, pas « must be do ».</p></div>`,
  audio:'English is spoken here. The bridge is being repaired. The museum was built in 1890. The painting has been found. The results will be announced on Monday. Tickets can be bought online.'},

 {kind:'Méthode', h:'Turning an active sentence into the passive',
  p:`<p><b>Quand :</b> quand l’auteur de l’action est inconnu, évident ou peu important, ou pour garder le même sujet d’une phrase à l’autre, comme dans un article. <b>Pourquoi ça marche :</b> le complément de l’actif devient le sujet ; <i lang="en">be</i> reprend le temps du verbe actif ; le verbe devient participe passé. <b>Comment :</b></p>
<ol><li>Trouve le <b>complément</b> du verbe actif : il devient le sujet (attention à l’accord de <i lang="en">be</i> au singulier ou au pluriel).</li><li>Repère le <b>temps</b> du verbe actif et mets <i lang="en">be</i> à ce temps.</li><li>Ajoute le <b>participe passé</b> du verbe.</li><li>Décide si <b>by + auteur</b> est utile. Le plus souvent, non. Le reste de la phrase (lieu, moment) ne change pas.</li></ol>`,
  demo:{enonce:'Mets au passif : <i lang="en">Thieves have stolen two paintings from a gallery in Leeds.</i>',
   etapes:[{f:'Nouveau sujet : <i lang="en">two paintings</i>',w:'C’est ce qui a été volé. C’est un pluriel : <i lang="en">be</i> sera au pluriel.'},
    {f:'Temps : <i lang="en">have stolen</i> = present perfect → <i lang="en">have been</i>',w:'Au present perfect, <i lang="en">be</i> devient <i lang="en">have been</i> (ou <i lang="en">has been</i> au singulier).'},
    {f:'Participe passé de <i lang="en">steal</i> : <i lang="en">stolen</i>',w:'<i lang="en">steal – stole – stolen</i>, un verbe irrégulier.'},
    {f:'<i lang="en">by thieves</i> ? Inutile.',w:'Qui vole des tableaux, sinon des voleurs&nbsp;? L’auteur est évident, on le supprime.'}],
   conclusion:'<i lang="en">Two paintings have been stolen from a gallery in Leeds.</i>'}},

 {kind:'Pratique', h:'Your turn: present simple passive',
  p:`<p>Rewrite the sentence in the passive. Do not mention who does the action.</p><p><b>Question:</b> <i lang="en">Someone cleans the offices every evening.</i></p>`, lab:'Your sentence',
  txt:['The offices are cleaned every evening.','Every evening the offices are cleaned.'],
  why:'Le complément <i lang="en">the offices</i> devient sujet (pluriel → <i lang="en">are</i>), le présent simple donne <i lang="en">are cleaned</i>. <i lang="en">by someone</i> n’apporte rien : on le supprime.'},

 {kind:'Pratique', h:'Your turn: past simple passive',
  p:`<p>Rewrite the sentence in the passive. You can keep or remove <i lang="en">by the police</i>.</p><p><b>Question:</b> <i lang="en">The police arrested three men near the station last night.</i></p>`, lab:'Your sentence',
  txt:[...X('Three men were arrested',['','by the police'],['near the station last night','last night near the station']),...X('Last night three men were arrested',['','by the police'],'near the station'),'Three men were arrested near the station by the police last night.'],
  why:'<i lang="en">Three men were arrested near the station last night.</i> Prétérit actif (<i lang="en">arrested</i>) → <i lang="en">were arrested</i>. <i lang="en">by the police</i> est correct, mais inutile : ce sont toujours les policiers qui arrêtent.'},

 {kind:'Pratique', h:'Your turn: present perfect passive',
  p:`<p>Rewrite the sentence in the passive, without <i lang="en">they</i>. This is news, with no precise time.</p><p><b>Question:</b> <i lang="en">They have cancelled tonight’s concert because of the storm.</i></p>`, lab:'Your sentence',
  txt:['Tonight’s concert has been cancelled because of the storm.','Because of the storm, tonight’s concert has been cancelled.','The concert tonight has been cancelled because of the storm.','Tonight’s concert has been called off because of the storm.','Tonight’s concert’s been cancelled because of the storm.'],
  why:'<i lang="en">have cancelled</i> → <i lang="en">has been cancelled</i> : le sujet <i lang="en">tonight’s concert</i> est singulier, donc <i lang="en">has</i>. En anglais britannique, <i lang="en">cancelled</i> prend deux L (américain : <i lang="en">canceled</i>).'},

 {kind:'Pratique', h:'Your turn: a modal in the passive',
  p:`<p>Rewrite this rule in the passive, the way it would appear on a sign.</p><p><b>Question:</b> <i lang="en">You must switch off all mobile phones during the exam.</i></p>`, lab:'Your sentence',
  txt:X(['All mobile phones','Mobile phones','All phones'],['must be switched off','must be turned off'],['during the exam','']),
  why:'Modal + <b>be</b> + participe : <i lang="en">All mobile phones must be switched off during the exam.</i> Le modal ne change pas ; seul le verbe qui suit devient <i lang="en">be switched</i>.'},

 {kind:'Pratique', h:'Your turn: “on m’a…”',
  p:`<p>Translate into English. Remember: the person becomes the subject.</p><p><b>Question:</b> « On m’a proposé un poste à Londres. »</p>`, lab:'Your sentence',
  txt:X(['I was offered','I have been offered','I got offered'],['a job','a position','a post'],'in London'),
  why:'<i lang="en">I was offered a job in London</i> (ou <i lang="en">I’ve been offered…</i> si c’est une nouvelle toute fraîche). Avec <i lang="en">offer</i>, la personne devient sujet du passif : la tournure « A job was offered to me » existe, mais elle sonne lourde.'},

 {kind:'Pratique', h:'Put the passive sentence in order',
  p:`<p>Tap the words in the right order to make a sentence from a local news website.</p><p><b>Question:</b> what is happening to the old bridge?</p>`,
  ordre:['The old bridge','is','being','repaired','at the moment'], alt:['At the moment the old bridge is being repaired'],
  why:'<i lang="en">The old bridge is being repaired at the moment.</i> Présent continu passif : <i lang="en">is being</i> + participe. Les travaux sont en cours, maintenant.'},

 {kind:'Vocabulaire', h:'Reading headlines',
  p:`<p>Les titres de presse anglais ont leur propre grammaire, très compacte. Si on ne la connaît pas, <i lang="en">PAINTING FOUND IN GARAGE</i> ou <i lang="en">MAYOR TO QUIT</i> sont difficiles à comprendre.</p>
<div class="def"><ul><li>On supprime les articles et le verbe <i lang="en">be</i>.</li><li>Le <b>présent simple</b> raconte un événement passé récent : <i lang="en">STORM HITS COAST</i> = a storm has hit the coast.</li><li>Le <b>participe passé seul</b> est un passif : <i lang="en">PAINTING FOUND</i> = a painting has been found.</li><li><b>to + verbe</b> annonce le futur : <i lang="en">MAYOR TO QUIT</i> = the mayor is going to resign.</li><li>On préfère les mots courts et forts (liste ci-dessous).</li></ul></div>`,
  mots:[['to quit','démissionner, quitter (titre de presse)','BANK BOSS QUITS'],['a row','une dispute, une polémique (rime avec how)','ROW OVER NEW CYCLE LANES'],['to slam','critiquer violemment','PARENTS SLAM SCHOOL LUNCH PRICES'],['to axe','supprimer (des emplois, un service)','200 JOBS AXED AT CAR PLANT'],['a bid','une tentative','TEENAGER IN BID TO SAIL ROUND THE WORLD'],['to vow','promettre solennellement','MAYOR VOWS TO CUT TRAFFIC'],['to probe / a probe','enquêter / une enquête','POLICE PROBE MUSEUM BREAK-IN'],['to back','soutenir','VOTERS BACK NEW STADIUM']]},

 {kind:'Pratique', h:'Your turn: from headline to sentence',
  p:`<p>Here is a headline: <i lang="en">MAYOR TO OPEN NEW BRIDGE</i>. Complete the full sentence with the missing verb form (2 to 3 words).</p><p><b>Question:</b> <i lang="en">The mayor ___ the new bridge.</i></p>`, lab:'Missing words',
  txt:['is going to open','will open','is to open','is opening','is due to open'],
  why:'Dans un titre, <b>to + verbe</b> annonce un événement futur : <i lang="en">The mayor is going to open</i> (ou <i lang="en">will open</i>) <i lang="en">the new bridge</i>. Ce n’est pas un but (« pour ouvrir »).'},

 {kind:'Prononciation', h:'Weak forms: was, were, been',
  p:`<p>Dans une phrase passive, <i lang="en">be</i> est un petit mot grammatical : il n’est <b>pas accentué</b> et se prononce en <b>forme faible</b>. L’accent tombe sur le participe et sur les noms qui portent le sens.</p>
<div class="def"><ul><li><b>was</b> → /wəz/, comme « weuz », très bref.</li><li><b>were</b> → /wə/, presque « weu ».</li><li><b>been</b> → /bɪn/ en anglais britannique, court comme « bine » sans le e, et non /biːn/ (<i lang="en">bean</i>, le haricot).</li><li><b>can be</b> → /kən bi/.</li></ul></div>
<div class="ex"><p><i lang="en">The <b>paint</b>ing was <b>sto</b>len in <b>March</b>.</i><br><i lang="en">Two <b>men</b> were ar<b>rest</b>ed.</i> (<i lang="en">arrested</i> : -ed se dit /ɪd/ après t ou d)<br><i lang="en">It’s been <b>found</b>.</i></p></div>
<div class="warn"><p>Le francophone accentue souvent <i lang="en">was</i> et <i lang="en">been</i>, ce qui casse le rythme et attire l’attention sur le mauvais mot. Lis vite le petit mot, appuie sur le participe.</p></div>`,
  audio:'The painting was stolen in March. Two men were arrested. It’s been found. Tickets can be bought online.'},

 {kind:'Lecture', h:'A local news story',
  p:`<p>Read this article from a local news website. You can also listen to it.</p>
<div class="blk" data-t="Ring lost 40 years ago returned to owner"><p lang="en">A gold wedding ring that was lost in a field in 1984 has finally been returned to its owner. Margaret Hill, 78, from a small village near York, lost the ring while she was helping her husband with the potato harvest. “I was heartbroken,” she said. “We searched that field for weeks, but it was never found.”</p><p lang="en">Last month, the ring was discovered by Daniel Price, a 34-year-old nurse whose hobby is metal detecting. “At first I thought it was a piece of rubbish,” he explained. “Then I saw the initials inside.” Daniel posted a photo on a local community page, and the post was shared more than 5,000 times in two days. It was eventually seen by Margaret’s granddaughter.</p><p lang="en">The ring was given back to Margaret at a small ceremony on Saturday. Her husband, John, died in 2015. “It feels like a part of him has come home,” she said. Daniel has been invited to Sunday lunch next week.</p></div>
<p><b>Question:</b> how did Margaret find out that her ring had been found?</p>`,
  audio:'A gold wedding ring that was lost in a field in 1984 has finally been returned to its owner. Margaret Hill, 78, from a small village near York, lost the ring while she was helping her husband with the potato harvest. “I was heartbroken,” she said. “We searched that field for weeks, but it was never found.” Last month, the ring was discovered by Daniel Price, a 34-year-old nurse whose hobby is metal detecting. “At first I thought it was a piece of rubbish,” he explained. “Then I saw the initials inside.” Daniel posted a photo on a local community page, and the post was shared more than 5,000 times in two days. It was eventually seen by Margaret’s granddaughter. The ring was given back to Margaret at a small ceremony on Saturday. Her husband, John, died in 2015. “It feels like a part of him has come home,” she said. Daniel has been invited to Sunday lunch next week.',
  opts:['Daniel phoned her after finding her address inside the ring.','Her granddaughter saw a post that had been shared online.','The farmer found the ring during the potato harvest.','She read about it in a national newspaper.'], ans:1,
  why:'<i lang="en">The post was shared more than 5,000 times… It was eventually seen by Margaret’s granddaughter.</i> C’est sa petite-fille qui a vu la publication partagée. <i lang="en">Eventually</i> = finalement (pas « éventuellement »).'},

 {kind:'Dictée', h:'Dictation: a traffic report',
  p:'Listen and write the sentence exactly. You can listen as many times as you like and use “Plus lentement”.',
  dictee:'The road has been closed and drivers are being asked to avoid the area.',
  why:'Deux passifs : present perfect <i lang="en">has been closed</i> et présent continu <i lang="en">are being asked</i>. Dans <i lang="en">been</i>, deux E ; <i lang="en">area</i> commence par un A.'},

 {kind:'Oral', h:'Read it like a newsreader',
  p:`<p>Listen, then say the sentence aloud. Use weak forms for <i lang="en">have been</i> and <i lang="en">is being</i>, and stress the important words: <i lang="en">Two <b>men</b> have been ar<b>rest</b>ed, and the <b>paint</b>ing is being <b>checked</b> by <b>ex</b>perts.</i></p>`,
  dire:'Two men have been arrested, and the painting is being checked by experts.',
  note:'Si un mot reste en rouge, réécoute-le avec « Plus lentement », puis recommence.'},

 {kind:'Oral', h:'Tell a news story',
  p:`<p>Talk for about one minute. Tell a friend about a news story you have read or heard recently (real or invented): what happened, where and when, who was involved, and what has been done since. Use at least three passive forms.</p>`,
  oral:{modele:'I read an amazing story last week. A fourteen-year-old girl from Wales was given an award for saving a dog. She was walking home from school when she heard a dog in a frozen lake. She went onto the ice and pulled it out. She was taken to hospital because she was very cold, but she wasn’t badly hurt. The dog has been returned to its owner, and the story was shared thousands of times online. She has even been invited to meet the mayor.',
   criteres:['I said what happened, where and when','I used at least three passive forms (was given, was taken, has been returned…)','I used the past simple for finished events and the present perfect for recent news','I said what has happened since','I used weak forms for was and been']}},

 {kind:'Écriture', h:'Write a short news article',
  p:`<p>Write a short article (about 120 words) for your local news website about a real or invented event in your town: a festival, an accident, a rescue, a new building… Give it a headline. Say what happened, where and when, and what has been done since. Use at least three passive forms and quote one person.</p>`,
  ecrire:{min:100, modele:'VOLUNTEERS SAVE VILLAGE LIBRARY\nA village library that was going to be closed in June has been saved by a group of local volunteers. The library in Ashford Green was opened in 1962, but last year the council announced that it could no longer pay for it. “We were shocked,” said Helen Ward, 52, who has used the library since she was a child. “It is much more than a building.”\nMore than 3,000 signatures were collected in two months, and £20,000 was raised at concerts and cake sales. From next month, the library will be run by thirty volunteers, and it will be open six days a week. According to the council, the building will also be repainted this summer. Reading sessions for children are being planned for the autumn.',
   criteres:['I wrote a short headline',{t:'I used the passive (is, was, been… + past participle)', re:'\\b(is|are|was|were|been|being|be)\\s+(\\w+ed|\\w+en|built|found|held|hit|hurt|left|lost|made|sold|sent|told|caught|brought|seen|given|known|shown|bought|kept|paid|put|run|won|shut)\\b'},{t:'I used the present perfect passive (has / have been…)', re:'\\b(has|have)\\s+been\\s+\\w+'},{t:'I quoted someone or gave a source (said, according to…)', re:'\\b(said|says|explained|told|according to)\\b'},'I said what happened, where and when','I said what has been done since, or what will be done']}},

 {kind:'Récapitulatif', h:'Ce qu’il faut retenir',
  p:`<div class="keep"><ul><li><b>Passif = be + participe passé.</b> <i lang="en">be</i> porte le temps, le participe ne change jamais. <i lang="en">by + auteur</i> seulement si c’est utile.</li><li>Les temps : <i lang="en">is done</i> (présent), <i lang="en">is being done</i> (en cours), <i lang="en">was done</i> (prétérit), <i lang="en">has been done</i> (present perfect), <i lang="en">will be done</i>, <i lang="en">can / must / should be done</i>.</li><li>Méthode : complément → sujet, <i lang="en">be</i> au temps de l’actif, participe passé, auteur seulement s’il apporte une information.</li><li>« On » se traduit souvent par un passif. « On m’a dit / proposé » = <i lang="en">I was told / offered</i>. « Je suis né » = <i lang="en">I was born</i>.</li><li>Passé composé : <i lang="en">was found</i> avec un moment précis, <i lang="en">has been found</i> pour une nouvelle sans date.</li><li><i lang="en">The news is…</i> (indénombrable). <i lang="en">according to, to make the headlines, to go viral, to release a statement, an eyewitness</i>.</li><li>Titres : pas d’article ni de <i lang="en">be</i> ; présent = passé récent, participe seul = passif, <i lang="en">to</i> + verbe = futur. <i lang="en">quit, row, slam, axe, bid, vow, probe, back</i>.</li><li>Prononciation : formes faibles <i lang="en">was /wəz/, were /wə/, been /bɪn/</i>.</li></ul></div>`},

 {kind:'Mission', h:'The six o’clock news',
  p:'You are listening to the radio news. Listen to the bulletin, then answer the questions one by one. You can listen again at any time.',
  audio:'Good evening. Here are the headlines at six o’clock. Heavy rain has caused flooding across the south-west of England. More than two hundred homes have been flooded, and several roads have been closed. Drivers are being advised not to travel unless their journey is absolutely necessary. In Exeter, around fifty people were rescued from their homes by firefighters last night. Nobody was seriously injured. More rain is expected tomorrow, and schools in the area will be closed until Wednesday. In other news, a new bridge over the river in Bristol will be opened by the mayor on Friday. The bridge, which took four years to build, can only be used by pedestrians and cyclists.', cache:true,
  parts:[
   {q:'a) How many people were rescued in Exeter?', opts:['About fifteen','About fifty','About two hundred','More than two hundred'], ans:1, hint:'Listen for the name Exeter, then for the number just after it.', why:'<i lang="en">Around fifty people were rescued from their homes by firefighters</i> : environ cinquante personnes. Les deux cents, ce sont les maisons inondées.'},
   {q:'b) What are drivers being asked to do?', opts:['To drive more slowly','To avoid all unnecessary journeys','To help the firefighters','To use the new bridge'], ans:1, hint:'Listen for the passive <i lang="en">are being advised</i>.', why:'<i lang="en">Drivers are being advised not to travel unless their journey is absolutely necessary</i> : ne voyager que si c’est indispensable.'},
   {q:'c) Complete the sentence from the bulletin with the future passive of <i lang="en">close</i>: <i lang="en">Schools in the area ___ until Wednesday.</i>', lab:'Missing words', txt:['will be closed','are going to be closed'], hint:'Future with <i lang="en">will</i>: <i lang="en">will be</i> + past participle.', why:'<i lang="en">Schools in the area will be closed until Wednesday.</i> Futur passif : <i lang="en">will be</i> + participe passé.'},
   {q:'d) Rewrite in the passive and keep the doer: <i lang="en">The mayor will open the new bridge on Friday.</i>', lab:'Your sentence', txt:['The new bridge will be opened by the mayor on Friday.','The new bridge will be opened on Friday by the mayor.','On Friday the new bridge will be opened by the mayor.'], hint:'The new subject is <i lang="en">the new bridge</i>. Add <i lang="en">by the mayor</i>, because the doer is important here.', why:'<i lang="en">The new bridge will be opened by the mayor on Friday.</i> Ici, l’auteur (le maire) est une information : on garde <i lang="en">by the mayor</i>.'}],
  sol:'<p lang="en">Heavy rain has caused flooding in the south-west of England: more than 200 homes have been flooded, several roads have been closed, and drivers are being advised not to travel. In Exeter, about fifty people were rescued last night. Schools will be closed until Wednesday. A new bridge in Bristol will be opened by the mayor on Friday; it can only be used by pedestrians and cyclists.</p><p>Remarque la variété des passifs : present perfect (<i lang="en">have been flooded</i>) pour les nouvelles, prétérit (<i lang="en">were rescued</i>) avec <i lang="en">last night</i>, présent continu (<i lang="en">are being advised</i>), futur (<i lang="en">will be closed</i>) et modal (<i lang="en">can only be used</i>).</p>'},

 {kind:'Mission', h:'Fake news?',
  p:`<p>A friend has sent you a post that is going viral. Then you find an article in the local paper. Read both, then answer.</p>
<div class="blk" data-t="Post shared 40,000 times"><p lang="en">BREAKING!!! Millbridge Central Station is going to be CLOSED for TWO YEARS from Monday. All trains cancelled. The council has kept this secret. Share before this post is deleted!!!</p></div>
<div class="blk" data-t="Millbridge Post · Station work: the facts"><p lang="en">A post claiming that Millbridge Central Station will be closed for two years has been shared more than 40,000 times since Saturday. However, the claim is false. According to the rail company, only one of the station’s four platforms will be closed, and only for six weeks, while it is being repaired. “No trains will be cancelled,” a spokesperson said. “Some services will be moved to other platforms, and passengers will be informed by text message.” The work was announced in a press release in March, and all the information can be found on the company’s website.</p></div>`,
  parts:[
   {q:'a) What is really going to happen?', opts:['The station will be closed for two years.','One platform will be closed for six weeks.','All trains will be cancelled for six weeks.','The station will be moved to another place.'], ans:1, hint:'Look for <i lang="en">According to the rail company</i> in the article.', why:'<i lang="en">Only one of the station’s four platforms will be closed, and only for six weeks</i> : un seul quai, pour six semaines.'},
   {q:'b) Why is the post an example of fake news?', opts:['It was written by a journalist.','It says the work was kept secret, but it was announced in March.','It was shared only a few times.','It quotes a spokesperson from the rail company.'], ans:1, hint:'Compare <i lang="en">kept this secret</i> in the post with the last sentence of the article.', why:'Le post affirme que tout a été caché (<i lang="en">kept this secret</i>), alors que les travaux <i lang="en">were announced in a press release in March</i>.'},
   {q:'c) Rewrite in the passive, without the doer: <i lang="en">The rail company will inform passengers by text message.</i>', lab:'Your sentence', txt:['Passengers will be informed by text message.','Passengers will be informed by text.'], hint:'The new subject is <i lang="en">passengers</i>. Here <i lang="en">by text message</i> is not the doer: keep it.', why:'<i lang="en">Passengers will be informed by text message.</i> Attention : <i lang="en">by text message</i> indique le moyen, pas l’auteur ; on le garde.'},
   {q:'d) Translate: « D’après la compagnie, aucun train ne sera supprimé. »', lab:'Your sentence', txt:[...X(['According to the company','According to the rail company'],['no trains will be cancelled','no train will be cancelled','none of the trains will be cancelled']),...X(['No trains will be cancelled','No train will be cancelled'],['according to the company','according to the rail company'])], hint:'« D’après » = <i lang="en">according to</i>. « Supprimer un train » = <i lang="en">to cancel a train</i>; use the future passive.', why:'<i lang="en">According to the company, no trains will be cancelled.</i> Futur passif : <i lang="en">will be cancelled</i>. Ne dis pas « according to me » : pour son propre avis, on dit <i lang="en">in my opinion</i>.'}],
  sol:'<p>Le post viral est faux : selon la compagnie ferroviaire, seul un des quatre quais sera fermé pendant six semaines, pour réparation. Aucun train ne sera supprimé (<i lang="en">no trains will be cancelled</i>), certains seront déplacés sur d’autres quais, et les voyageurs seront prévenus par SMS (<i lang="en">passengers will be informed by text message</i>). Les travaux avaient été annoncés en mars : rien n’était secret. Avant de partager, vérifie la source (<i lang="en">check the source</i>).</p>'},
]},
{subj:'en', sem:'b1', id:'en-b1-reported', o:8, h:'He said that…', p:'Rapporter ce que quelqu’un a dit, demandé ou ordonné : le discours indirect, say, tell et ask, la concordance des temps et les repères de temps.', steps:[
 {kind:'Écoute', h:'News from the landlord',
  p:`<p>By the end of this unit, you will be able to report what people said, asked and told you to do, and pass on a message accurately.</p>
<p>Sam meets his sister Lily for a coffee. He tells her about a phone call from his landlord. <b>Listen without reading</b>, then answer. The script will appear after your answer.</p>
<p><b>Question:</b> what did the landlord suggest?</p>`,
  audio:[['Lily','You look worried. What’s up?'],['Sam','My landlord rang this morning. He said he was selling the flat.'],['Lily','Oh no! Did he say when?'],['Sam','He said he wanted to put it on the market in the spring, and that I would have to move out by the end of June.'],['Lily','That’s awful. Did he give you a reason?'],['Sam','He told me his daughter was getting married and he needed the money for the wedding. Then he asked me if I had ever thought about buying a flat.'],['Lily','Wait… was he asking you if you wanted to buy it?'],['Sam','Exactly. He said he would give me a good price because I had always paid the rent on time.'],['Lily','And what did you tell him?'],['Sam','I told him I would think about it. He asked me to call him back before Friday.'],['Lily','Well, you did tell me last month that you were tired of renting…']], cache:true,
  opts:['That Sam should move out immediately','That Sam could buy the flat','That Sam should pay more rent','That Sam could stay until the wedding'], ans:1,
  why:'<i lang="en">He asked me if I had ever thought about buying a flat… He said he would give me a good price</i> : le propriétaire propose à Sam d’acheter l’appartement. Sam ne répète pas les mots exacts du propriétaire : il les <b>rapporte</b> (<i lang="en">he said he was selling, he asked me if…, he asked me to call him back</i>). C’est le discours indirect, le sujet de l’unité.'},

 {kind:'Vocabulaire', h:'Passing on what people said',
  p:`<p>Here are verbs and chunks for reporting what people say and for passing on messages. Tap a line to hear it, then say it aloud.</p>`,
  mots:[['to say (that)…','dire (que)…','She said that she was busy.'],['to tell someone (that)…','dire à quelqu’un (que)…','He told me that the shop was closed.'],['to tell someone to do something','dire à quelqu’un de faire quelque chose','My boss told me to take a day off.'],['to ask someone to do something','demander à quelqu’un de faire quelque chose','She asked me to close the window.'],['to ask if / whether…','demander si…','He asked if I was free on Friday.'],['to explain (to someone) that…','expliquer (à quelqu’un) que…','She explained to me that the train was late.'],['to reply that…','répondre que…','I replied that I didn’t know.'],['to promise to do something','promettre de faire quelque chose','He promised to call back.'],['to tell the truth / to tell a lie','dire la vérité / mentir','I’m sure she told the truth.'],['to take a message','prendre un message','She isn’t here. Can I take a message?'],['to pass on a message','transmettre un message','Don’t worry, I’ll pass on your message.'],['to call someone back','rappeler quelqu’un (au téléphone)','Could you ask him to call me back?'],['to remind someone to do something','rappeler à quelqu’un de faire quelque chose','Remind me to buy some milk.'],['to get back to someone','revenir vers quelqu’un, recontacter','I’ll get back to you by Friday.'],['apparently','apparemment, il paraît que','Apparently, the meeting has been cancelled.'],['word for word','mot pour mot','I can’t remember what he said word for word.'],['to wonder if…','se demander si…','I wonder if she got my message.']],
  note:'<b>Piège :</b> « rappeler » a deux traductions. Au téléphone : <i lang="en">to call back</i>. « Rappeler quelque chose à quelqu’un » : <i lang="en">to remind someone</i> (<i lang="en">Remind me to call Mum</i>). Et <i lang="en">to remember</i> = se souvenir.'},

 {kind:'Pratique', h:'Your turn: leave a message',
  p:`<p>You call a colleague, but her assistant answers. Translate your request into English.</p><p><b>Question:</b> « Pouvez-vous lui demander de me rappeler ? »</p>`, lab:'Your sentence',
  txt:X(['Can you','Could you','Would you'],['ask her'],['to call me back','to ring me back','to phone me back','to call me','to give me a call','to give me a call back'],['','please']),
  why:'<i lang="en">Could you ask her to call me back?</i> Structure : <b>ask + personne + to + verbe</b>. « me rappeler » au téléphone = <i lang="en">to call me back</i> (britannique aussi : <i lang="en">to ring me back</i>).'},

 {kind:'Grammaire', h:'Say or tell?',
  p:`<p>Le français n’a qu’un verbe, « dire ». L’anglais en a deux, <b>say</b> et <b>tell</b>, et ils ne se construisent pas de la même façon. Sam dit : <i lang="en">He <b>said</b> he was selling the flat</i> mais <i lang="en">He <b>told me</b> his daughter was getting married</i>.</p>
<div class="def"><ul><li><b>say (that)</b> + phrase, sans personne : <i lang="en">She said (that) she was tired.</i> Si on veut nommer la personne : <b>say something to someone</b> : <i lang="en">She said hello to me.</i></li><li><b>tell + personne + (that)</b> + phrase : <i lang="en">She told <b>me</b> (that) she was tired.</i></li><li><b>tell + personne + to + verbe</b> pour un ordre : <i lang="en">He told me to wait.</i></li></ul></div>
<div class="idea"><p>Le truc : <b>tell</b> est presque toujours suivi directement de la personne à qui on parle ; <b>say</b> ne l’est jamais. Quelques expressions figées : <b>tell</b> <i lang="en">the truth, a lie, a story, a joke, the time, the difference</i> ; <b>say</b> <i lang="en">hello, goodbye, sorry, yes, no, thank you, a word</i>.</p></div>
<div class="ex"><p><i lang="en">He said (that) he was late.</i> = <i lang="en">He told us (that) he was late.</i><br><i lang="en">She told me a funny story. She said sorry to everyone.</i><br><i lang="en">Can you tell the difference between these two words?</i></p></div>
<div class="warn"><p>Pièges des francophones : <b>✗ He said me…</b> → <i lang="en">He told me…</i> ; <b>✗ She told that…</b> → <i lang="en">She said that…</i> ; <b>✗ He explained me…</b> → <i lang="en">He explained <b>to</b> me…</i> (comme <i lang="en">say</i>, <i lang="en">explain</i> veut <i lang="en">to</i> devant la personne). À l’inverse, <b>ask</b> n’en veut pas : <b>✗ I asked to him</b> → <i lang="en">I asked him</i>.</p></div>`,
  audio:'He said he was late. He told us he was late. She told me a funny story. She said sorry to everyone. He explained to me that the train was late.'},

 {kind:'Pratique', h:'Your turn: say or tell?',
  p:`<p>Complete the sentence with the correct form of <i lang="en">say</i> or <i lang="en">tell</i>. Write the two missing words in order, separated by a comma.</p><p><b>Question:</b> <i lang="en">Tom ___ me he was sorry, but he didn’t ___ why.</i></p>`, lab:'Two words',
  txt:['told, say'],
  why:'<i lang="en">Tom <b>told</b> me</i> : la personne suit directement le verbe, donc <i lang="en">tell</i> (prétérit <i lang="en">told</i>). <i lang="en">He didn’t <b>say</b> why</i> : pas de personne après le verbe, donc <i lang="en">say</i> (base verbale après <i lang="en">didn’t</i>). On pourrait dire <i lang="en">he didn’t tell <b>me</b> why</i>, mais pas « he didn’t tell why ».'},

 {kind:'Grammaire', h:'Reported statements: tenses go back',
  p:`<p>Le propriétaire a dit au téléphone : <i lang="en">“I’m selling the flat. You’ll have to move out by June.”</i> Sam rapporte : <i lang="en">He said he <b>was</b> selling the flat and that I <b>would</b> have to move out by June.</i> Les verbes ont reculé d’un cran dans le passé.</p>
<div class="def"><p>Quand le verbe introducteur est au passé (<i lang="en">said, told</i>), on fait la <b>concordance des temps</b> (<i lang="en">backshift</i>) :</p><ul><li>présent simple → prétérit : <i lang="en">“I live in Bern.”</i> → <i lang="en">She said she <b>lived</b> in Bern.</i></li><li>présent continu → prétérit continu : <i lang="en">“I’m working.”</i> → <i lang="en">He said he <b>was working</b>.</i></li><li>present perfect et prétérit → past perfect : <i lang="en">“I’ve finished.” / “I saw her.”</i> → <i lang="en">He said he <b>had finished</b> / he <b>had seen</b> her.</i></li><li><b>will → would</b>, <b>can → could</b>, <b>must → had to</b> (ou <i lang="en">must</i>), <b>am going to → was going to</b>.</li><li><i lang="en">would, could, should, might</i> ne changent pas.</li></ul></div>
<div class="idea"><p>Les paroles appartiennent maintenant au passé, alors tout le récit recule. Bonne nouvelle : c’est exactement le réflexe du français. « Il a dit qu’il <b>était</b> fatigué, qu’il <b>avait</b> fini, qu’il <b>viendrait</b> » : <i lang="en">would</i> correspond au conditionnel français.</p></div>
<div class="ex"><p><i lang="en">“We can’t come,” they said.</i> → <i lang="en">They said they <b>couldn’t</b> come.</i><br><i lang="en">“It will rain,” she said.</i> → <i lang="en">She said it <b>would</b> rain.</i></p></div>
<div class="warn"><p>Le recul n’est pas obligatoire si ce qui est dit est <b>toujours vrai</b> au moment où on le rapporte : <i lang="en">She told me she <b>lives</b> in Bern</i> (elle y habite encore) est correct. Et si le verbe introducteur est au présent, rien ne bouge : <i lang="en">He <b>says</b> he’s tired.</i> En cas de doute, et dans les exercices de cette unité, fais le recul : il est toujours correct.</p></div>`,
  audio:'I’m selling the flat. He said he was selling the flat. You’ll have to move out. He said I would have to move out. We can’t come. They said they couldn’t come.'},

 {kind:'Méthode', h:'Reporting a statement step by step',
  p:`<p><b>Quand :</b> pour raconter ce que quelqu’un a dit, plus tard ou ailleurs. <b>Pourquoi ça marche :</b> on change de point de vue : ce n’est plus la personne qui parle, c’est toi qui racontes, à un autre moment et à un autre endroit. <b>Comment :</b></p>
<ol><li>Choisis le verbe : <b>said</b> (sans personne) ou <b>told + personne</b>. <i lang="en">that</i> est facultatif.</li><li>Change les <b>pronoms et possessifs</b> selon qui raconte : <i lang="en">I → he / she, my → his / her, you → I / me</i>…</li><li><b>Recule le temps</b> du verbe (présent → prétérit, <i lang="en">will → would</i>…).</li><li>Change les <b>repères de temps et de lieu</b> si on rapporte un autre jour ou ailleurs : <i lang="en">today → that day</i>, <i lang="en">tomorrow → the next day / the following day</i>, <i lang="en">yesterday → the day before / the previous day</i>, <i lang="en">next week → the following week</i>, <i lang="en">last week → the week before</i>, <i lang="en">here → there</i>, <i lang="en">this → that</i>, <i lang="en">now → then</i>.</li></ol>`,
  demo:{enonce:'Lundi dernier, Mia t’a dit : <i lang="en">“I’m starting my new job here tomorrow.”</i> Une semaine plus tard, tu rapportes sa phrase.',
   etapes:[{f:'Verbe : <i lang="en">Mia told me (that)…</i>',w:'Elle t’a parlé à toi : <i lang="en">told me</i>. On pourrait aussi dire <i lang="en">Mia said (that)…</i>'},
    {f:'Pronoms : <i lang="en">I → she</i>, <i lang="en">my → her</i>',w:'Ce n’est plus Mia qui parle, c’est toi qui parles d’elle.'},
    {f:'Temps : <i lang="en">am starting → was starting</i>',w:'Présent continu → prétérit continu.'},
    {f:'Repères : <i lang="en">here → there</i>, <i lang="en">tomorrow → the next day</i>',w:'Tu n’es plus au même endroit, et « demain » est déjà passé : on dit <i lang="en">the next day</i> (ou <i lang="en">the following day</i>).'}],
   conclusion:'<i lang="en">Mia told me (that) she was starting her new job there the next day.</i>'}},

 {kind:'Pratique', h:'Your turn: report a statement',
  p:`<p>Report what Tom said. Use backshift.</p><p><b>Question:</b> <i lang="en">“I’m really tired and I want to go home,” said Tom.</i></p>`, lab:'Your sentence',
  txt:[...X('Tom said',['','that'],'he was really tired',['and','and that'],'he wanted to go home'),...X('Tom said',['','that'],'he was really tired and wanted to go home')],
  why:'<i lang="en">Tom said (that) he was really tired and (that) he wanted to go home.</i> <i lang="en">I’m → he was</i>, <i lang="en">I want → he wanted</i>. On ne dit pas « Tom said me » : sans personne, <i lang="en">said</i> seul.'},

 {kind:'Pratique', h:'Your turn: will and time words',
  p:`<p>Last Monday, Anna told you something. Report it today, a week later. Change the pronouns, the tense and the time word.</p><p><b>Question:</b> <i lang="en">“I will call you tomorrow,” Anna told me.</i></p>`, lab:'Your sentence',
  txt:X(['Anna told me','Anna said'],['','that'],['she would','she’d'],'call me',['the next day','the following day','the day after']),
  why:'<i lang="en">Anna told me (that) she would call me the next day.</i> <i lang="en">I → she</i>, <i lang="en">you → me</i>, <i lang="en">will → would</i>, <i lang="en">tomorrow → the next day</i> (ou <i lang="en">the following day</i>), puisque ce « demain » est passé.'},

 {kind:'Méthode', h:'Reporting a question step by step',
  p:`<p>Sam raconte : <i lang="en">He asked me <b>if I had ever thought</b> about buying a flat.</i> La question du propriétaire était <i lang="en">“Have you ever thought about buying a flat?”</i> Une question rapportée <b>n’est plus une question</b> : c’est une phrase affirmative introduite par <b>ask</b>.</p>
<p><b>Quand :</b> pour rapporter une question. <b>Pourquoi ça marche :</b> c’est <i lang="en">asked</i> qui porte l’idée de question ; la suite reprend l’ordre normal sujet + verbe. <b>Comment :</b></p>
<ol><li>Question fermée (réponse oui ou non) : <b>asked (+ personne) + if</b> (ou <b>whether</b>, plus soutenu).</li><li>Question ouverte : <b>asked (+ personne) + mot interrogatif</b> (<i lang="en">where, when, why, what time, how much…</i>).</li><li>Ensuite, <b>ordre affirmatif</b> : sujet + verbe, <b>sans</b> <i lang="en">do / does / did</i> et sans inversion.</li><li>Pronoms, temps et repères changent comme pour une déclaration. Pas de point d’interrogation.</li></ol>
<p>Le français fait pareil : « Il m’a demandé où <b>je travaillais</b> », pas « où travaillais-je ». Le piège vient de l’habitude de l’inversion anglaise : <b>✗ He asked me where did I work</b> → <i lang="en">He asked me where I worked.</i></p>`,
  demo:{enonce:'Rapporte les deux questions du propriétaire de Sam : <i lang="en">“Have you ever thought about buying a flat?”</i> et <i lang="en">“When can you give me an answer?”</i>',
   etapes:[{f:'Type : la 1re est fermée → <i lang="en">if</i> ; la 2e commence par <i lang="en">when</i> → on garde <i lang="en">when</i>',w:'On répond à la première par oui ou non, à la seconde par une date.'},
    {f:'Ordre affirmatif : <i lang="en">have you thought → you had thought</i> ; <i lang="en">can you give → you could give</i>',w:'Le sujet repasse devant le verbe, comme dans une phrase normale.'},
    {f:'Pronoms et temps : <i lang="en">you → I</i>, <i lang="en">me → him</i> ; <i lang="en">have → had</i>, <i lang="en">can → could</i>',w:'C’est Sam qui raconte ; le propriétaire devient <i lang="en">he / him</i>.'},
    {f:'Ponctuation : un point final, pas de point d’interrogation',w:'La phrase rapportée est une affirmation.'}],
   conclusion:'<i lang="en">He asked me if I had ever thought about buying a flat. He asked me when I could give him an answer.</i>'}},

 {kind:'Pratique', h:'Your turn: a wh- question',
  p:`<p>Report the question. Use backshift and normal word order.</p><p><b>Question:</b> <i lang="en">“Where do you work?” she asked me.</i></p>`, lab:'Your sentence',
  txt:['She asked me where I worked.','She asked where I worked.','She wanted to know where I worked.'],
  why:'<i lang="en">She asked me where I worked.</i> On garde <i lang="en">where</i>, on supprime <i lang="en">do</i>, on met le sujet avant le verbe et on recule le temps : <i lang="en">work → worked</i>. Pas de point d’interrogation.'},

 {kind:'Pratique', h:'Your turn: a yes/no question',
  p:`<p>Report the question with <i lang="en">if</i> or <i lang="en">whether</i>.</p><p><b>Question:</b> <i lang="en">“Are you coming to the party on Saturday?” he asked me.</i></p>`, lab:'Your sentence',
  txt:X(['He asked me','He asked','He wanted to know'],['if','whether'],'I was coming to the party',['on Saturday','on the Saturday','']),
  why:'<i lang="en">He asked me if (whether) I was coming to the party on Saturday.</i> Question fermée → <i lang="en">if</i> ; <i lang="en">are you coming → I was coming</i> : pronom changé, ordre affirmatif, temps reculé.'},

 {kind:'Grammaire', h:'Orders and requests',
  p:`<p>Le propriétaire a dit : <i lang="en">“Call me back before Friday, please.”</i> Sam rapporte : <i lang="en">He <b>asked me to call</b> him back before Friday.</i> Pour un ordre ou une demande, on ne recule aucun temps : on utilise un infinitif.</p>
<div class="def"><ul><li>Ordre, consigne : <b>tell + personne + to + verbe</b> : <i lang="en">“Sit down!”</i> → <i lang="en">The teacher told us to sit down.</i></li><li>Demande polie : <b>ask + personne + to + verbe</b> : <i lang="en">“Could you close the door, please?”</i> → <i lang="en">She asked me to close the door.</i></li><li>À la forme négative : <b>not to + verbe</b> : <i lang="en">“Don’t touch it!”</i> → <i lang="en">He told me not to touch it.</i></li></ul></div>
<div class="idea"><p>L’impératif (ou la question polie <i lang="en">Could you…?</i>) disparaît et devient <i lang="en">to</i> + verbe, exactement comme le français « il m’a dit <b>de</b> m’asseoir », « elle m’a demandé <b>de</b> fermer la porte ». Le choix du verbe donne le ton : <i lang="en">tell</i> pour un ordre, <i lang="en">ask</i> pour une demande. Les pronoms changent toujours : <i lang="en">“Call <b>me</b>”</i> → <i lang="en">He asked me to call <b>him</b>.</i></p></div>
<div class="ex"><p><i lang="en">“Please wait here,” the nurse said to me.</i> → <i lang="en">The nurse asked me to wait there.</i><br><i lang="en">“Don’t be late!” our coach told us.</i> → <i lang="en">Our coach told us not to be late.</i></p></div>
<div class="warn"><p><b>✗ He said me to wait</b> → <i lang="en">He told me to wait.</i> <b>✗ She told us to don’t be late</b> → <i lang="en">She told us <b>not to</b> be late.</i> <b>✗ He asked to me to help</b> → <i lang="en">He asked me to help.</i> <b>✗ She told me that I call her</b> → <i lang="en">She told me to call her.</i></p></div>`,
  audio:'Call me back before Friday, please. He asked me to call him back before Friday. Don’t be late! Our coach told us not to be late.'},

 {kind:'Pratique', h:'Put the reported order in order',
  p:`<p>Your doctor said to you: <i lang="en">“Don’t drink coffee after six.”</i> Tap the words in the right order to report it.</p><p><b>Question:</b> what did the doctor tell you?</p>`,
  ordre:['The doctor','told','me','not','to drink','coffee','after six'],
  why:'<i lang="en">The doctor told me not to drink coffee after six.</i> Ordre négatif rapporté : <i lang="en">told + personne + <b>not to</b> + verbe</i>.'},

 {kind:'Pratique', h:'Your turn: a polite request',
  p:`<p>Report Maria’s request with <i lang="en">asked</i>. Change the pronouns.</p><p><b>Question:</b> <i lang="en">“Could you send me the photos, please?” Maria asked me.</i></p>`, lab:'Your sentence',
  txt:X('Maria asked me',['to send her the photos','to send the photos to her']),
  why:'<i lang="en">Maria asked me to send her the photos.</i> Une demande polie (<i lang="en">Could you…?</i>) se rapporte avec <i lang="en">ask + personne + to + verbe</i>, pas avec <i lang="en">if</i> : Maria ne demandait pas si tu en étais capable. <i lang="en">me → her</i>.'},

 {kind:'Prononciation', h:'Said, says and weak forms',
  p:`<p>Les verbes du discours indirect reviennent sans cesse : autant bien les prononcer.</p>
<div class="def"><ul><li><b>said</b> se prononce /sed/, comme <i lang="en">red</i> ou <i lang="en">bed</i>, et non « sèïd ».</li><li><b>says</b> se prononce /sez/, et non « sèïz ». Seul <i lang="en">say</i> a le son « èï ».</li><li><b>asked</b> : /ɑːskt/, une seule syllabe. Le <i lang="en">-ed</i> se dit /t/ : pas de « ask-ed ».</li><li><b>that</b> et <b>to</b> sont en forme faible : /ðət/ et /tə/. <i lang="en">He said that he was late</i> : « hi <b>sed</b> ðeut i weuz <b>late</b> ».</li></ul></div>
<div class="warn"><p>Le francophone prononce souvent <i lang="en">said</i> comme il s’écrit, avec « aï » ou « èï ». C’est une des fautes les plus remarquées. Retiens la rime : <i lang="en">said – red – bed – head</i>.</p></div>
<div class="ex"><p><i lang="en">He <b>said</b> that he was <b>tired</b>. She <b>says</b> she’s <b>fine</b>. I <b>asked</b> if she was <b>ready</b>. They <b>told</b> me to <b>wait</b>.</i></p></div>`,
  audio:'He said that he was tired. She says she’s fine. I asked if she was ready. They told me to wait.'},

 {kind:'Lecture', h:'The best advice I was ever given',
  p:`<p>Read this blog post. You can also listen to it.</p>
<div class="blk" data-t="The best advice I was ever given"><p lang="en">When I was nineteen, I worked in a café in Brighton for a summer. On my first day, I broke three cups and gave a customer the wrong change. I was sure I would be fired. At the end of the day, the owner, an old Italian man called Enzo, asked me to sit down. I thought he was going to tell me not to come back.</p><p lang="en">Instead, he asked me what I wanted to do with my life. I told him I didn’t know, and that I was worried I wasn’t good at anything. He laughed and said that nobody was good at anything on their first day. Then he told me something I have never forgotten. He said that the only people who never made mistakes were the people who never tried anything new. He told me to come back the next day and to be a little slower with the cups.</p><p lang="en">I stayed for three summers. Years later, when I was nervous before my first job interview, I remembered his words. I got the job.</p></div>
<p><b>Question:</b> what did Enzo tell the writer?</p>`,
  audio:'When I was nineteen, I worked in a café in Brighton for a summer. On my first day, I broke three cups and gave a customer the wrong change. I was sure I would be fired. At the end of the day, the owner, an old Italian man called Enzo, asked me to sit down. I thought he was going to tell me not to come back. Instead, he asked me what I wanted to do with my life. I told him I didn’t know, and that I was worried I wasn’t good at anything. He laughed and said that nobody was good at anything on their first day. Then he told me something I have never forgotten. He said that the only people who never made mistakes were the people who never tried anything new. He told me to come back the next day and to be a little slower with the cups. I stayed for three summers. Years later, when I was nervous before my first job interview, I remembered his words. I got the job.',
  opts:['That he should look for another job','That making mistakes is normal when you try something new','That he had to pay for the broken cups','That he was the best waiter in the café'], ans:1,
  why:'<i lang="en">He said that the only people who never made mistakes were the people who never tried anything new</i> : seuls ceux qui n’essaient jamais rien ne se trompent jamais. Remarque <i lang="en">he asked me what I wanted</i> (question rapportée) et <i lang="en">he told me to come back</i> (ordre rapporté).'},

 {kind:'Dictée', h:'Dictation: what she asked',
  p:'Listen and write the sentence exactly. You can listen as many times as you like and use “Plus lentement”.',
  dictee:'She asked me if I had finished the book and told me to bring it back.',
  why:'Une question rapportée (<i lang="en">asked me if I had finished</i>, ordre affirmatif) et un ordre rapporté (<i lang="en">told me to bring it back</i>). <i lang="en">Finished</i> : deux syllabes, le <i lang="en">-ed</i> se dit /t/.'},

 {kind:'Oral', h:'Repeat from memory',
  p:`<p>The sentence is not written this time. Listen, then say it from memory. Watch the pronunciation of <i lang="en">told</i> and the weak form of <i lang="en">that</i>.</p>`,
  dire:{t:'She told me that she would call me back the next day.', cache:true},
  note:'Si la reconnaissance vocale ne comprend pas un mot, réécoute avec « Plus lentement », puis recommence.'},

 {kind:'Oral', h:'Report a conversation',
  p:`<p>Talk for about one minute. Report a conversation you had recently, with a friend, a colleague, a neighbour or a shop assistant. Say what the other person said, what they asked you, and what they told or asked you to do.</p>`,
  oral:{modele:'Last week I met an old friend from school in the street. She asked me what I was doing now, and I told her that I was working in a bank. She said she had moved back to the city two months before and that she was looking for a flat. She asked me if I knew any good areas, and I told her that the rents near the station were quite cheap. Before we left, she asked me to send her my number and told me that we should have dinner together soon. I promised to call her the following week.',
   criteres:['I used said and told correctly (told + person)','I reported a question with if or a question word, in normal word order','I reported a request or an order with asked / told + person + to','I moved the tenses back (was, had, would…)','I pronounced said /sed/ and asked in one syllable']}},

 {kind:'Écriture', h:'Pass on a phone message',
  p:`<p>You share a flat with Alex. While Alex was out, his mother phoned and you took the call. Here is what she said:</p>
<div class="blk" data-t="On the phone"><p lang="en">“Hi, it’s Alex’s mum. I’m calling because I can’t come on Saturday. Alex’s dad isn’t well: he’s got the flu. Can Alex call me back tonight? And please tell him not to forget his grandmother’s birthday on Monday! Oh, and does he still need the old sofa? We’re giving it away next week.”</p></div>
<p>Write a message to Alex (about 120 words) and report <b>everything</b> she said. Use <i lang="en">said, told, asked</i> and backshift.</p>`,
  ecrire:{min:90, modele:'Hi Alex,\nYour mum called this afternoon while you were out. She said that she was calling because she couldn’t come on Saturday. She explained that your dad wasn’t well and that he had the flu. She asked if you could call her back tonight, so don’t forget! She also asked me to tell you not to forget your grandmother’s birthday on Monday. Finally, she wanted to know whether you still needed the old sofa, because they were giving it away the following week. I told her that I would pass on the message as soon as you got home. She sounded fine, so don’t worry too much about your dad.\nSee you later,\nJo',
   criteres:[{t:'I used said, told or explained', re:'\\b(said|told|explained)\\b'},{t:'I reported a question with if or whether', re:'\\b(asked|wanted to know|wondered)( me| you| him| her| us| them)? (if|whether)\\b'},{t:'I reported a request or an order with told / asked + person + to', re:'\\b(told|asked) (me|you|him|her|us|them) (not )?to \\w+'},{t:'I moved the tenses back (was, couldn’t, had, would…)', re:'\\b(was|were|could|had|would)\\b|\\b(couldn|wasn|weren)[\'’]t\\b'},'I changed the pronouns (I → she, my → his, Alex → you…)','I reported all five pieces of information']}},

 {kind:'Récapitulatif', h:'Ce qu’il faut retenir',
  p:`<div class="keep"><ul><li><b>say (that)</b> sans personne, ou <i lang="en">say something to someone</i> ; <b>tell + personne (that)</b>. <i lang="en">tell the truth / a lie / a story</i> ; <i lang="en">say hello / sorry</i>. <i lang="en">explain <b>to</b> someone</i>, <i lang="en">ask someone</i> (sans <i lang="en">to</i>).</li><li>Concordance des temps après <i lang="en">said / told</i> : présent → prétérit, présent continu → prétérit continu, present perfect et prétérit → past perfect, <i lang="en">will → would, can → could, must → had to, am going to → was going to</i>. Pas obligatoire si c’est toujours vrai.</li><li>Changer les pronoms et les repères : <i lang="en">today → that day, tomorrow → the next day, yesterday → the day before, next week → the following week, here → there, this → that</i>.</li><li>Questions : <i lang="en">asked (me) if / whether…</i> ou <i lang="en">asked (me) where / when…</i> + <b>ordre affirmatif</b>, sans <i lang="en">do / did</i>, sans point d’interrogation.</li><li>Ordres et demandes : <i lang="en">told / asked + personne + (not) to + verbe</i>.</li><li>Messages : <i lang="en">take a message, pass on a message, call someone back, remind someone to…, get back to someone</i>.</li><li>Prononciation : <i lang="en">said /sed/, says /sez/, asked</i> en une syllabe, <i lang="en">that /ðət/</i> faible.</li></ul></div>`},

 {kind:'Mission', h:'A message from the dentist',
  p:'You are staying with your friend Daniel. He is in the shower, and you listen to a voicemail for him on the landline. Listen, then answer the questions one by one. You can listen again at any time.',
  audio:'Hi, this is Karen from Greenway Dental Surgery. This message is for Mr Daniel Ross. I’m calling about your appointment on Thursday the fourteenth. I’m afraid Dr Patel is ill this week, so we have to cancel it. We can offer you a new appointment next Tuesday at half past nine, or on Wednesday at four. Could you call us back before Friday to let us know which one you prefer? And please don’t forget to bring your new insurance card. Thanks. Bye.', cache:true,
  parts:[
   {q:'a) Why has the appointment been cancelled?', opts:['The surgery is closed for the holidays.','The dentist is ill.','Daniel missed his last appointment.','Daniel’s insurance card has expired.'], ans:1, hint:'Listen for the name of the dentist.', why:'<i lang="en">I’m afraid Dr Patel is ill this week, so we have to cancel it</i> : le dentiste est malade.'},
   {q:'b) Which new appointments can Daniel choose from?', opts:['Tuesday at 9.30 or Wednesday at 4 pm','Thursday at 9.30 or Friday at 4 pm','Tuesday at 4 pm or Wednesday at 9.30','Wednesday at 9.30 only'], ans:0, hint:'<i lang="en">Half past nine</i> = 9.30.', why:'<i lang="en">Next Tuesday at half past nine, or on Wednesday at four</i> : mardi 9 h 30 ou mercredi 16 h.'},
   {q:'c) You report the message to Daniel. Complete with two words: <i lang="en">Karen asked you ___ them back before Friday.</i>', lab:'Missing words', txt:['to call','to ring','to phone'], hint:'A request: <i lang="en">ask + person + to + verb</i>.', why:'<i lang="en">Karen asked you to call them back before Friday.</i> La demande polie <i lang="en">Could you call us back?</i> devient <i lang="en">asked you to call them back</i>.'},
   {q:'d) Report her last request, starting with <i lang="en">She told you…</i>', lab:'Your sentence', txt:X('She told you',['not to forget to bring','to bring','to remember to bring'],['your new insurance card','your new insurance card with you']), hint:'<i lang="en">“Please don’t forget…”</i> becomes <i lang="en">told you not to…</i> Change <i lang="en">your</i>? No: Daniel is still <i lang="en">you</i>.', why:'<i lang="en">She told you not to forget to bring your new insurance card.</i> L’impératif négatif devient <i lang="en">not to</i> + verbe. Ici <i lang="en">your</i> ne change pas, car tu parles à Daniel.'}],
  sol:'<p lang="en">Daniel, Karen from the dental surgery called. She said that Dr Patel was ill, so they had to cancel your appointment on Thursday the fourteenth. She said they could offer you next Tuesday at half past nine or Wednesday at four. She asked you to call them back before Friday, and she told you not to forget to bring your new insurance card.</p><p>On recule les temps (<i lang="en">is → was, have to → had to, can → could</i>), on rapporte la demande avec <i lang="en">asked you to</i> et l’ordre négatif avec <i lang="en">told you not to</i>.</p>'},

 {kind:'Mission', h:'The witness statement',
  p:`<p>A cyclist was knocked off her bike by a van. A police officer is interviewing a witness, Mrs Grant. Read the interview. Then help the officer write the report, in reported speech.</p>
<div class="blk" data-t="Interview"><p lang="en"><b>Officer:</b> Where were you when the accident happened?<br><b>Mrs Grant:</b> I was waiting at the bus stop opposite the bakery.<br><b>Officer:</b> Did you see the driver’s face?<br><b>Mrs Grant:</b> Not really. He was wearing a cap. But I’ve seen that red van in this street before.<br><b>Officer:</b> Can you describe the cyclist?<br><b>Mrs Grant:</b> She was young, maybe twenty, and she wasn’t wearing a helmet. She’s going to be all right, isn’t she?<br><b>Officer:</b> Don’t worry, she’ll be fine. Please call us if you remember anything else.</p></div>`,
  parts:[
   {q:'a) What did Mrs Grant say about the van?', opts:['She said she had never seen it before.','She said she had seen it in that street before.','She said it was waiting at the bus stop.','She said the driver had given her his cap.'], ans:1, hint:'Find <i lang="en">I’ve seen that red van</i>. Present perfect → past perfect.', why:'<i lang="en">“I’ve seen that red van in this street before”</i> → <i lang="en">She said she had seen the red van in that street before.</i>'},
   {q:'b) Report the officer’s first question. Start with <i lang="en">The officer asked Mrs Grant…</i>', lab:'Your sentence', txt:X(['The officer asked Mrs Grant','The officer asked her','He asked her'],['where she had been','where she was'],['when the accident happened','when the accident had happened']), hint:'Keep <i lang="en">where</i>, then subject + verb. <i lang="en">you were → she had been</i> (or <i lang="en">she was</i>).', why:'<i lang="en">The officer asked Mrs Grant where she had been when the accident happened.</i> Ordre affirmatif après <i lang="en">where</i>. Avec un prétérit, le recul au past perfect est facultatif à l’oral : <i lang="en">where she was</i> est aussi accepté.'},
   {q:'c) Report the second question: <i lang="en">“Did you see the driver’s face?”</i> Start with <i lang="en">He asked her…</i>', lab:'Your sentence', txt:X(['He asked her','The officer asked her','The officer asked Mrs Grant'],['if','whether'],['she had seen','she saw'],'the driver’s face'), hint:'A yes/no question: <i lang="en">if</i> or <i lang="en">whether</i>. No <i lang="en">did</i> any more.', why:'<i lang="en">He asked her if she had seen the driver’s face.</i> <i lang="en">did</i> disparaît : <i lang="en">did you see → she had seen</i> (ou <i lang="en">she saw</i>).'},
   {q:'d) Report the officer’s last request. Start with <i lang="en">He asked her…</i>', lab:'Your sentence', txt:X(['He asked her','The officer asked her','The officer asked Mrs Grant','He told her','The officer told her'],['to call them','to call the police','to phone them','to phone the police','to contact them','to contact the police'],['if she remembered anything else','if she remembered anything more']), hint:'A request: <i lang="en">asked her to</i> + verb. <i lang="en">us</i> becomes <i lang="en">them</i> (the police), and <i lang="en">you remember → she remembered</i>.', why:'<i lang="en">He asked her to call them if she remembered anything else.</i> Demande → <i lang="en">asked + personne + to</i> ; <i lang="en">us → them</i> ; le présent <i lang="en">remember</i> recule en <i lang="en">remembered</i>.'}],
  sol:'<p lang="en">The officer asked Mrs Grant where she had been when the accident happened. She said she had been waiting at the bus stop opposite the bakery. He asked her if she had seen the driver’s face. She said she hadn’t really seen it because he was wearing a cap, but that she had seen the red van in that street before. She said the cyclist was young and that she hadn’t been wearing a helmet. The officer told her that the cyclist would be fine and asked her to call them if she remembered anything else.</p><p>Toutes les règles de l’unité : <i lang="en">said / told / asked</i>, recul des temps, <i lang="en">this → that</i>, questions en ordre affirmatif, demandes avec <i lang="en">to</i>.</p>'},
]},
{subj:'en', sem:'b1', id:'en-b1-work', o:9, h:'At work', p:'Passer un entretien d’embauche et écrire un e-mail formel : les modaux d’obligation (must, have to, mustn’t, don’t have to) et de déduction (must be, might be, can’t be).', steps:[
 {kind:'Écoute', h:'A job interview',
  p:`<p>By the end of this unit, you will be able to talk about rules and obligations at work, make deductions, answer interview questions and write a formal email.</p>
<p>Nadia is applying for a job as an events coordinator at a conference centre in Edinburgh. <b>Listen without reading</b> to part of her interview, then answer. The script will appear after your answer.</p>
<p><b>Question:</b> why does Nadia want to change jobs?</p>`,
  audio:[['Interviewer','Thanks for coming in, Nadia. So, can you tell me a bit about your current job?'],['Nadia','Of course. I work for a conference centre in Lyon. I’m in charge of business events, so I have to deal with clients, suppliers and the technical team.'],['Interviewer','And why do you want to leave?'],['Nadia','I really enjoy my job, but I’ve been there for five years and I feel I need a new challenge. I’d also like to use my English every day.'],['Interviewer','I see. As you know, this job involves a lot of evening work. Our coordinators have to be at every event, and some events finish very late.'],['Nadia','That’s not a problem. I often work late in my current job.'],['Interviewer','Good. You wouldn’t have to work on Sundays, though. The centre is closed.'],['Nadia','That sounds perfect. Can I ask what the next step is?'],['Interviewer','We’re seeing four more candidates this week. You don’t need to send us anything else, but you must bring your passport if we invite you back for a second interview.']], cache:true,
  opts:['She doesn’t get on with her colleagues.','She wants a new challenge and to use her English more.','She wants to stop working in the evening.','Her conference centre is closing.'], ans:1,
  why:'<i lang="en">I feel I need a new challenge. I’d also like to use my English every day.</i> Elle aime son travail, mais veut un nouveau défi et parler anglais tous les jours. Remarque les modaux : <i lang="en">I have to deal with…, coordinators have to be at every event, you don’t need to send…, you must bring your passport</i>.'},

 {kind:'Vocabulaire', h:'Jobs and the workplace',
  p:`<p>Here are useful chunks for talking about your job and for a job interview. Tap a line to hear it, then say it aloud.</p>`,
  mots:[['to apply for a job','postuler à un emploi','I’ve applied for three jobs this month.'],['a job interview','un entretien d’embauche','My job interview is on Monday at ten.'],['to be in charge of','être responsable de, diriger','She’s in charge of the sales team.'],['to be responsible for','être chargé de','I’m responsible for the company’s website.'],['to deal with','s’occuper de, gérer','I deal with complaints from customers.'],['to meet a deadline','respecter un délai','We worked all weekend to meet the deadline.'],['to work overtime','faire des heures supplémentaires','In December, we often work overtime.'],['flexible hours','des horaires flexibles','The job offers flexible hours.'],['a salary','un salaire (fixe, annuel)','The salary is £32,000 a year.'],['a full-time / part-time job','un emploi à plein temps / à temps partiel','She has a part-time job in a bookshop.'],['work experience','l’expérience professionnelle','Do you have any work experience?'],['a CV / a résumé','un CV (britannique / américain)','Please send your CV and a covering letter.'],['an internship','un stage (en entreprise)','I did a six-month internship in a bank.'],['to get promoted','obtenir une promotion','She got promoted after two years.'],['to hand in your notice','donner sa démission','He handed in his notice on Friday.'],['to work well under pressure','bien travailler sous pression','I work well under pressure.']],
  note:'<b>Faux amis du travail :</b> « un stage » = <i lang="en">an internship</i> ou <i lang="en">a work placement</i> (<i lang="en">a stage</i> est une scène de théâtre) ; « une formation » = <i lang="en">training</i> (indénombrable) ; « postuler » = <i lang="en">to apply for</i> (pas « to postulate »). <i lang="en">experience</i> au sens d’expérience professionnelle est <b>indénombrable</b> : <i lang="en">a lot of experience</i>, jamais « experiences » ni « an experience professional ».'},

 {kind:'Pratique', h:'Your turn: describe your job',
  p:`<p>Translate into English, using a chunk from the list.</p><p><b>Question:</b> « Je suis responsable d’une équipe de six personnes. »</p>`, lab:'Your sentence',
  txt:X(['I am in charge of','I am responsible for','I manage','I lead','I run'],['a team of six people','a team of six','a six-person team']),
  why:'<i lang="en">I’m in charge of a team of six people</i> (ou <i lang="en">I’m responsible for…, I manage…</i>). Attention : <i lang="en">in charge <b>of</b></i> mais <i lang="en">responsible <b>for</b></i>.'},

 {kind:'Grammaire', h:'Obligation: must, have to, need to',
  p:`<p>Dans l’entretien, la recruteuse dit <i lang="en">Our coordinators <b>have to</b> be at every event</i> et <i lang="en">You <b>must</b> bring your passport</i>. Les deux expriment une obligation. Quelle différence&nbsp;?</p>
<div class="def"><ul><li><b>must + base verbale</b> (sans <i lang="en">to</i>, sans -s) : obligation que <b>celui qui parle</b> juge nécessaire, ou règle écrite et formelle : <i lang="en">I must call my mum tonight. Visitors must sign in at reception.</i></li><li><b>have to / has to + base verbale</b> : obligation qui vient de <b>l’extérieur</b> (règlement, contrat, situation) : <i lang="en">I have to wear a uniform at work.</i></li><li><b>need to + base verbale</b> : c’est nécessaire : <i lang="en">I need to finish this report today.</i></li></ul></div>
<div class="idea"><p><i lang="en">must</i>, c’est « je trouve que c’est indispensable » ; <i lang="en">have to</i>, c’est « c’est la règle, je n’ai pas le choix ». Dans la conversation, surtout en anglais britannique, <i lang="en">have to</i> est bien plus fréquent ; <i lang="en">must</i> domine dans les règlements et les annonces : <i lang="en">Applicants must have a degree.</i></p></div>
<div class="ex"><p><i lang="en">She has to start at 7 am.</i> (son contrat l’exige)<br><i lang="en">I really must stop eating so much chocolate.</i> (ma propre décision)</p></div>
<div class="warn"><p><i lang="en">must</i> n’a ni passé ni futur : on emprunte <i lang="en">have to</i>. Hier : <b>had to</b> (<i lang="en">I had to stay late</i>). Demain : <b>will have to</b>. Questions et négations de <i lang="en">have to</i> se font avec <i lang="en">do</i> : <i lang="en">Do you have to…? She doesn’t have to…</i> Fautes typiques : <b>✗ I must to go</b>, <b>✗ she musts</b>, <b>✗ I musted</b>, <b>✗ Have you to work?</b></p></div>`,
  audio:'Our coordinators have to be at every event. You must bring your passport. I had to stay late yesterday. Do you have to work on Saturdays?'},

 {kind:'Grammaire', h:'Mustn’t or don’t have to?',
  p:`<p>À l’affirmatif, <i lang="en">must</i> et <i lang="en">have to</i> sont proches. À la forme négative, ils deviennent <b>opposés</b>. C’est l’un des pièges les plus coûteux pour un francophone au travail.</p>
<div class="def"><ul><li><b>mustn’t</b> (<i lang="en">must not</i>) = <b>interdiction</b> : « il ne faut pas, c’est interdit ». <i lang="en">You mustn’t smoke in the building.</i> On dit aussi <i lang="en">You’re not allowed to…, You can’t…</i></li><li><b>don’t have to</b> = <b>absence d’obligation</b> : « pas besoin, tu n’es pas obligé, c’est comme tu veux ». <i lang="en">You don’t have to wear a tie.</i> Même sens : <b>don’t need to</b> et, en anglais britannique un peu soutenu, <b>needn’t</b> : <i lang="en">You needn’t wear a tie.</i></li></ul></div>
<div class="idea"><p>Le français « tu ne dois pas » veut dire « c’est interdit » : c’est <i lang="en">mustn’t</i>. Mais si tu traduis « tu n’es pas obligé » par « you mustn’t », tu interdis quelque chose que tu voulais permettre&nbsp;! Pose-toi la question : est-ce <b>interdit</b> ou seulement <b>pas nécessaire</b>&nbsp;?</p></div>
<div class="ex"><p><i lang="en">You mustn’t tell anyone: it’s confidential.</i> (interdit)<br><i lang="en">You don’t have to come to the meeting: it’s optional.</i> (pas obligatoire)<br>Au passé : <i lang="en">We didn’t have to wear a uniform</i> (pas d’obligation) ; <i lang="en">We weren’t allowed to use our phones</i> (interdiction).</p></div>
<div class="warn"><p>Dans <i lang="en">mustn’t</i>, le premier t ne se prononce pas : /ˈmʌsnt/, « meusnt ». Et ne confonds pas <i lang="en">needn’t</i> (pas besoin) avec <i lang="en">mustn’t</i> (interdit).</p></div>`,
  audio:'You mustn’t smoke in the building. You don’t have to wear a tie. You needn’t wear a tie. You mustn’t tell anyone. It’s confidential.'},

 {kind:'Méthode', h:'Choosing the right modal of obligation',
  p:`<p><b>Quand :</b> chaque fois que tu parles de règles, de consignes ou de contraintes : un règlement, un contrat, un premier jour de travail. <b>Pourquoi ça marche :</b> chaque modal correspond à une situation précise, et trois questions suffisent pour la trouver. <b>Comment :</b></p>
<ol><li>Est-ce <b>nécessaire</b>, <b>interdit</b> ou <b>pas nécessaire</b>&nbsp;? → <i lang="en">must / have to</i>, <i lang="en">mustn’t</i>, <i lang="en">don’t have to / needn’t</i>.</li><li>Quel <b>moment</b>&nbsp;? Au passé : <i lang="en">had to / didn’t have to</i> ; au futur : <i lang="en">will have to / won’t have to</i>.</li><li>Qui impose&nbsp;? Règle écrite ou avis personnel → <i lang="en">must</i> ; contrainte extérieure, à l’oral → <i lang="en">have to</i>.</li></ol>`,
  demo:{enonce:'Complète le guide du nouvel employé : a) <i lang="en">Staff ___ wear their badge at all times.</i> b) <i lang="en">You ___ come in on Saturdays: it’s optional.</i> c) <i lang="en">Visitors ___ enter the kitchen.</i> d) <i lang="en">Last year, we ___ stay until 9 pm every day before the opening.</i>',
   etapes:[{f:'a) <i lang="en">must</i> (ou <i lang="en">have to</i>)',w:'C’est nécessaire, et c’est une règle écrite : <i lang="en">must</i> est naturel.'},
    {f:'b) <i lang="en">don’t have to</i> (ou <i lang="en">don’t need to, needn’t</i>)',w:'<i lang="en">optional</i> : pas nécessaire, mais pas interdit.'},
    {f:'c) <i lang="en">mustn’t</i> (ou <i lang="en">aren’t allowed to</i>)',w:'C’est une interdiction.'},
    {f:'d) <i lang="en">had to</i>',w:'Obligation au passé (<i lang="en">last year</i>) : <i lang="en">must</i> n’a pas de passé.'}],
   conclusion:'<i lang="en">Staff must wear their badge at all times. You don’t have to come in on Saturdays. Visitors mustn’t enter the kitchen. Last year, we had to stay until 9 pm.</i>'}},

 {kind:'Pratique', h:'Your turn: no obligation',
  p:`<p>Translate into English. Think: is it forbidden, or just not necessary?</p><p><b>Question:</b> « Tu n’es pas obligé de porter une cravate. »</p>`, lab:'Your sentence',
  txt:X(['You do not have to','You do not need to','You need not','You have not got to'],'wear a tie'),
  why:'Pas d’obligation : <i lang="en">You don’t have to wear a tie</i> (ou <i lang="en">don’t need to, needn’t</i>). « You mustn’t wear a tie » voudrait dire que la cravate est <b>interdite</b>.'},

 {kind:'Pratique', h:'Your turn: forbidden',
  p:`<p>Complete the safety rule with a modal that means “it is forbidden”.</p><p><b>Question:</b> <i lang="en">Employees ___ use their phones in the warehouse. It’s dangerous.</i></p>`, lab:'Missing word(s)',
  txt:['mustn’t','are not allowed to','can’t','are not permitted to'],
  why:'Interdiction : <i lang="en">mustn’t</i> (ou <i lang="en">aren’t allowed to, can’t</i>). <i lang="en">don’t have to</i> voudrait dire « ne sont pas obligés », ce qui n’a pas de sens ici.'},

 {kind:'Pratique', h:'Your turn: past obligation',
  p:`<p>Translate into English. Remember that <i lang="en">must</i> has no past form.</p><p><b>Question:</b> « Hier, j’ai dû rester au bureau jusqu’à 20 heures. »</p>`, lab:'Your sentence',
  txt:[...X(['Yesterday I had to stay','Yesterday, I had to stay'],['at the office','in the office','at work'],['until 8 pm','until 8 p.m.','till 8 pm','until eight','until eight o’clock','until 8','until eight in the evening','until 8 in the evening','until 20:00']),...X('I had to stay',['at the office','in the office','at work'],['until 8 pm','until 8 p.m.','till 8 pm','until eight','until eight o’clock','until 8','until eight in the evening','until 8 in the evening','until 20:00'],'yesterday')],
  why:'<i lang="en">Yesterday I had to stay at the office until 8 pm.</i> Au passé, <i lang="en">must</i> devient <b>had to</b>. En anglais, on dit plus souvent l’heure sur 12 heures : <i lang="en">8 pm</i> ou <i lang="en">eight in the evening</i>.'},

 {kind:'Grammaire', h:'Deduction: must, might, can’t',
  p:`<p>Ton collègue ne répond pas au téléphone. Tu dis : <i lang="en">He <b>must</b> be in a meeting.</i> Ici, <i lang="en">must</i> n’exprime pas une obligation : c’est une <b>déduction</b>, un raisonnement à partir d’un indice.</p>
<div class="def"><ul><li><b>must + be / verbe</b> : je suis presque sûr que c’est <b>vrai</b>. <i lang="en">The lights are on. Someone must be in the office.</i></li><li><b>might / may / could + be / verbe</b> : c’est <b>possible</b>. <i lang="en">She’s not answering. She might be on the phone.</i></li><li><b>can’t + be / verbe</b> : je suis presque sûr que c’est <b>faux</b>. <i lang="en">He can’t be the new manager: he looks about sixteen!</i></li><li>Pour une action en cours : <b>must / might / can’t + be + -ing</b>. <i lang="en">He must be working from home today.</i></li></ul></div>
<div class="idea"><p>Imagine une échelle de certitude : <i lang="en">must</i> (environ 95 %), <i lang="en">may / might / could</i> (50 %), <i lang="en">can’t</i> (5 %). Le français dit pareil « il doit être en réunion » pour une déduction : la ressemblance aide pour <i lang="en">must</i>, mais elle piège pour la forme négative.</p></div>
<div class="ex"><p><i lang="en">You’ve been travelling all day. You must be tired.</i><br><i lang="en">Take an umbrella. It might rain later.</i><br><i lang="en">That can’t be Anna’s car. She hasn’t got a driving licence.</i></p></div>
<div class="warn"><p>Le contraire de <i lang="en">must</i> (déduction) est <b>can’t</b>, pas <i lang="en">mustn’t</i> : « ça ne doit pas être vrai » = <i lang="en">It <b>can’t</b> be true</i>, jamais « It mustn’t be true ». Et pour une possibilité ici et maintenant, pas de <i lang="en">can</i> : <b>✗ She can be ill</b> → <i lang="en">She might / could be ill.</i> (<i lang="en">can</i> exprime une possibilité générale : <i lang="en">It can be cold in March.</i>)</p></div>`,
  audio:'He must be in a meeting. She might be on the phone. He can’t be the new manager. He must be working from home today. It can’t be true.'},

 {kind:'Méthode', h:'Making a deduction step by step',
  p:`<p><b>Quand :</b> tu n’es pas sûr, mais tu as des indices : un bureau vide, une lumière allumée, une voiture devant la maison. <b>Pourquoi ça marche :</b> ces modaux expriment un degré de certitude ; il suffit de mesurer ce que tu sais. <b>Comment :</b></p>
<ol><li>Regarde l’<b>indice</b> : que prouve-t-il, et à quel point&nbsp;?</li><li>Choisis le <b>degré</b> : sûr que oui → <i lang="en">must</i> ; possible → <i lang="en">might / may / could</i> ; sûr que non → <i lang="en">can’t</i>.</li><li>Choisis la <b>forme</b> : un état → modal + <i lang="en">be</i> + adjectif, nom ou lieu ; une action en ce moment → modal + <i lang="en">be</i> + verbe en <i lang="en">-ing</i>.</li></ol>`,
  demo:{enonce:'Il est 10 h. Ta collègue Emma n’est pas à son bureau. Que peux-tu dire avec chacun de ces indices&nbsp;? a) Sa tasse de café est encore chaude. b) Il y a une réunion au 3e étage ce matin. c) Son badge est sur le bureau, et il faut un badge pour sortir de l’immeuble. d) On entend sa voix dans la salle d’à côté, elle parle au téléphone.',
   etapes:[{f:'a) <i lang="en">She must be somewhere in the building.</i>',w:'Café chaud : elle était là il y a quelques minutes. Presque sûr → <i lang="en">must</i>.'},
    {f:'b) <i lang="en">She might be in the meeting.</i>',w:'Rien ne prouve qu’elle y est : c’est seulement possible → <i lang="en">might</i> (ou <i lang="en">may, could</i>).'},
    {f:'c) <i lang="en">She can’t be outside.</i>',w:'Sans badge, elle ne peut pas être sortie : presque sûr que non → <i lang="en">can’t</i>, jamais <i lang="en">mustn’t</i>.'},
    {f:'d) <i lang="en">She must be talking to a client.</i>',w:'Action en cours → <i lang="en">must be</i> + <i lang="en">-ing</i>. <i lang="en">a client</i> reste une supposition raisonnable : on pourrait dire <i lang="en">She might be talking to a client</i>.'}],
   conclusion:'<i lang="en">She must be somewhere in the building. She might be in the meeting, but she can’t be outside. She must be talking to someone on the phone.</i>'}},

 {kind:'Pratique', h:'Your turn: impossible',
  p:`<p>Complete with <i lang="en">must</i>, <i lang="en">might</i> or <i lang="en">can’t</i>.</p><p><b>Question:</b> <i lang="en">Her coat isn’t here and her computer is switched off. She ___ be in the office.</i></p>`, lab:'One word',
  txt:['can’t'],
  why:'Les deux indices montrent qu’elle est partie : presque sûr que non → <i lang="en">She can’t be in the office.</i> « mustn’t » serait une interdiction (« elle n’a pas le droit d’être au bureau »).'},

 {kind:'Pratique', h:'Your turn: almost certain',
  p:`<p>Tom works seventy hours a week. Translate the deduction into English.</p><p><b>Question:</b> « Il doit être épuisé. »</p>`, lab:'Your sentence',
  txt:X('He must be',['exhausted','very tired','really tired','tired','worn out','shattered']),
  why:'Déduction presque certaine : <i lang="en">He must be exhausted.</i> Ici, « doit » ne veut pas dire « est obligé » : c’est un raisonnement.'},

 {kind:'Pratique', h:'Put the deduction in order',
  p:`<p>Your colleague is not at her desk, but her status online says “active”. Tap the words in the right order.</p><p><b>Question:</b> what is a possible explanation?</p>`,
  ordre:['She','might','be working','from home','today'], alt:['Today she might be working from home'],
  why:'<i lang="en">She might be working from home today.</i> Possibilité (<i lang="en">might</i>) + action en cours (<i lang="en">be working</i>).'},

 {kind:'Prononciation', h:'Have to, has to, mustn’t',
  p:`<p>Ces modaux se prononcent souvent autrement qu’ils s’écrivent. Si tu les dis lettre par lettre, on te comprendra, mais tu auras du mal à les reconnaître à l’oral.</p>
<div class="def"><ul><li><b>have to</b> → /ˈhæftə/ : le v devient f devant <i lang="en">to</i>, « haf-teu ».</li><li><b>has to</b> → /ˈhæstə/ : « has-teu », avec un s dur. <b>had to</b> → /ˈhættə/.</li><li><b>must</b> en milieu de phrase → /məs/ : <i lang="en">You must be tired</i> = « you meus be tired ».</li><li><b>mustn’t</b> → /ˈmʌsnt/ : le premier t est muet, « meusnt ».</li></ul></div>
<div class="warn"><p>Le francophone prononce souvent <i lang="en">have to</i> avec un v bien sonore et <i lang="en">mustn’t</i> avec deux t. Écoute le modèle, puis répète la phrase en imitant le rythme : l’accent tombe sur les verbes qui portent le sens (<i lang="en">come, late</i>), pas sur les modaux.</p></div>`,
  dire:'You don’t have to come early, but you mustn’t be late.',
  note:'Si un mot reste en rouge, réécoute-le avec « Plus lentement », puis recommence.'},

 {kind:'Lecture', h:'A job advert',
  p:`<p>Read this job advert. You can also listen to it.</p>
<div class="blk" data-t="Events Assistant · Harbour View Hotel, Brighton"><p lang="en">Full-time, permanent. Salary: £26,500 a year. Start date: 1 March.</p><p lang="en">We are looking for an enthusiastic events assistant to join our busy team. You will help to organise weddings, conferences and private parties for up to 300 guests. You will deal with clients by phone and email, prepare rooms and equipment before each event, and make sure that everything runs smoothly.</p><p lang="en">Applicants must have at least one year’s experience in a hotel, a restaurant or an events company. You must be able to work evenings and some weekends. A good level of English is essential. A second language would be an advantage, but you don’t need to speak it fluently. You don’t have to have a driving licence.</p><p lang="en">We offer 28 days’ holiday, free meals during your shifts and flexible hours outside the busy summer season. To apply, please send your CV and a covering letter to Ms Laura Bennett, HR Manager, before 31 January.</p></div>
<p><b>Question:</b> which statement about applicants is true?</p>`,
  audio:'Events Assistant, Harbour View Hotel, Brighton. Full-time, permanent. Salary: twenty-six thousand five hundred pounds a year. Start date: the first of March. We are looking for an enthusiastic events assistant to join our busy team. You will help to organise weddings, conferences and private parties for up to three hundred guests. You will deal with clients by phone and email, prepare rooms and equipment before each event, and make sure that everything runs smoothly. Applicants must have at least one year’s experience in a hotel, a restaurant or an events company. You must be able to work evenings and some weekends. A good level of English is essential. A second language would be an advantage, but you don’t need to speak it fluently. You don’t have to have a driving licence. We offer twenty-eight days’ holiday, free meals during your shifts and flexible hours outside the busy summer season. To apply, please send your CV and a covering letter to Ms Laura Bennett, HR Manager, before the thirty-first of January.',
  opts:['They must speak a second language fluently.','They must be able to work some evenings and weekends.','They have to have a driving licence.','They must have worked in a hotel for three years.'], ans:1,
  why:'<i lang="en">You must be able to work evenings and some weekends.</i> La deuxième langue est un plus, sans obligation de la parler couramment (<i lang="en">you don’t need to</i>) ; le permis n’est pas exigé (<i lang="en">you don’t have to</i>) ; un an d’expérience suffit.'},

 {kind:'Vocabulaire', h:'Writing a formal email',
  p:`<p>Pour postuler, réclamer ou demander une information à une entreprise, on écrit un e-mail <b>formel</b>. Ses règles sont plus simples que celles de la lettre française, mais elles sont strictes.</p>
<div class="def"><ul><li><b>Salutation et formule finale vont ensemble.</b> Tu connais le nom : <i lang="en">Dear Ms Bennett</i> (titre + nom de famille) → <i lang="en">Yours sincerely</i>. Tu ne le connais pas : <i lang="en">Dear Sir or Madam</i> → <i lang="en">Yours faithfully</i> (britannique). En américain : <i lang="en">Sincerely</i>. <i lang="en">Kind regards</i> convient à un e-mail professionnel moins solennel.</li><li><b>Titres :</b> <i lang="en">Mr</i> pour un homme, <i lang="en">Ms</i> pour une femme (neutre, le plus sûr), sans le prénom : <i lang="en">Dear Mr Smith</i>, jamais « Dear Mr John ».</li><li><b>Plan :</b> pourquoi tu écris, les détails, ce que tu demandes, une phrase de clôture.</li><li><b>Registre :</b> pas de contractions (<i lang="en">I am</i>, pas <i lang="en">I’m</i>), pas de mots familiers (<i lang="en">info, thanks a lot, asap</i>), des demandes indirectes (<i lang="en">I would be grateful if you could…</i>).</li></ul></div>
<div class="warn"><p>Les longues formules françaises (« Veuillez agréer, Madame, l’expression de mes salutations distinguées ») n’existent pas : <i lang="en">Yours sincerely</i> suffit. Et dans <i lang="en">I look forward to <b>hearing</b> from you</i>, <i lang="en">to</i> est une préposition : il est suivi de <i lang="en">-ing</i>, pas de la base verbale.</p></div>`,
  mots:[['I am writing to…','Je vous écris pour…','I am writing to apply for the position of events assistant.'],['with regard to…','en ce qui concerne…','With regard to your email of 3 May, …'],['Please find attached…','Veuillez trouver ci-joint…','Please find attached my CV.'],['I would be grateful if you could…','Je vous serais reconnaissant(e) de…','I would be grateful if you could send me further information.'],['I look forward to hearing from you.','Dans l’attente de votre réponse.'],['Dear Sir or Madam','Madame, Monsieur'],['Yours sincerely / Yours faithfully','Veuillez agréer… (formule finale)','Yours sincerely, Nadia Rossi'],['Please do not hesitate to contact me.','N’hésitez pas à me contacter.','Please do not hesitate to contact me if you need any further information.'],['at your earliest convenience','dès que possible (formel)','Please reply at your earliest convenience.']]},

 {kind:'Pratique', h:'Your turn: make it formal',
  p:`<p>Rewrite this sentence in a formal style, for an email to a company you do not know.</p><p><b>Question:</b> <i lang="en">Can you send me more info about the job?</i></p>`, lab:'Your sentence', formel:true,
  txt:X(['I would be grateful if you could send me','Could you please send me','Could you send me','Would you be able to send me','Would you please send me','Please could you send me','I would appreciate it if you could send me'],['more information','further information','some more information','additional information','more details','further details'],['about the job','about the position','about the post','regarding the position','regarding the job','about the vacancy','concerning the position','on the position'],['','please']),
  why:'<i lang="en">I would be grateful if you could send me further information about the position.</i> Une demande indirecte et polie, <i lang="en">information</i> au lieu de <i lang="en">info</i>, et pas de contraction (<i lang="en">I would</i>, pas <i lang="en">I’d</i>).'},

 {kind:'Dictée', h:'Dictation: a formal opening',
  p:'Listen and write the sentence exactly. It is the first sentence of a job application. You can listen as many times as you like and use “Plus lentement”.',
  dictee:'I am writing to apply for the position of sales assistant advertised on your website.',
  why:'La phrase d’ouverture classique : <i lang="en">I am writing to apply for…</i> Attention à <i lang="en">apply <b>for</b></i>, à <i lang="en">position</i> (un seul S au milieu, puis -tion) et à <i lang="en">advertised</i> (avec un S).'},

 {kind:'Oral', h:'Answer an interview question',
  p:`<p>You are at a job interview. Answer the question below for about one minute: say why you want the job, describe what you do now, and give two or three strengths with an example. Then compare with the model.</p><p><b>Question:</b> <i lang="en">Why do you want this job, and what are your strengths?</i></p>`,
  oral:{modele:'I’d like this job because I really enjoy working with people, and I’m looking for a new challenge. At the moment, I work as a receptionist in a hotel in Geneva, where I’m responsible for welcoming guests and dealing with complaints. I think my main strengths are that I’m very organised and I work well under pressure. In my current job, I often have to deal with several problems at the same time, so I’ve learned to stay calm. I’m also a real team player, and I speak French, English and some German, which would be useful here.',
   criteres:['I said why I want the job','I described my current job or studies (I’m in charge of / responsible for…)','I gave two or three strengths with an example','I used at least one modal of obligation (have to, must…)','I spoke for about one minute without long pauses']}},

 {kind:'Écriture', h:'Write a formal email',
  p:`<p>Write an email (about 120 words) to Ms Laura Bennett to apply for the job of events assistant in the advert you read. Say which job you are applying for and where you saw it, describe your experience, say when you are available, mention your CV and finish politely. Use a formal style.</p>`,
  ecrire:{min:100, modele:'Dear Ms Bennett,\nI am writing to apply for the position of events assistant advertised on your website.\nI have worked as a receptionist at a conference centre in Geneva for two years. I am responsible for welcoming guests and dealing with clients by phone and email. I also help to organise business events for up to 200 people, so I know how important it is to work well under pressure.\nI speak French and English fluently and I have a good level of German. I am able to work evenings and weekends, and I could start on 1 March.\nPlease find attached my CV. I would be grateful if you could let me know if you need any further information.\nI look forward to hearing from you.\nYours sincerely,\nCamille Favre',
   criteres:[{t:'I started with Dear + title + surname (or Dear Sir or Madam)', re:'\\bdear (mr|mrs|ms|miss|dr|sir)\\b'},{t:'I said why I am writing (I am writing to…)', re:'\\bi am writing to\\b'},{t:'I made a polite, indirect request (I would be grateful if…, Could you…)', re:'\\b(i would be grateful|i would appreciate|could you|would you)\\b'},{t:'I ended with a formal closing (Yours sincerely, Yours faithfully, Kind regards)', re:'\\b(yours sincerely|yours faithfully|kind regards|best regards|sincerely)\\b'},'I did not use any contractions (I am, not I’m)','I described my experience and said when I am available']}},

 {kind:'Récapitulatif', h:'Ce qu’il faut retenir',
  p:`<div class="keep"><ul><li>Obligation : <b>must</b> (avis de celui qui parle, règle écrite), <b>have to</b> (contrainte extérieure, le plus courant à l’oral), <b>need to</b>. Toujours + base verbale, sans <i lang="en">to</i> après <i lang="en">must</i>. Passé : <i lang="en">had to</i> ; futur : <i lang="en">will have to</i> ; question : <i lang="en">Do you have to…?</i></li><li><b>mustn’t</b> = interdit ; <b>don’t have to / don’t need to / needn’t</b> = pas nécessaire. « Tu n’es pas obligé » ≠ <i lang="en">you mustn’t</i>.</li><li>Déduction : <b>must be</b> (presque sûr), <b>might / may / could be</b> (possible), <b>can’t be</b> (presque sûr que non, jamais <i lang="en">mustn’t</i>). Action en cours : <i lang="en">must be working</i>.</li><li>Travail : <i lang="en">apply for a job, be in charge of, be responsible for, deal with, meet a deadline, work overtime, work experience</i> (indénombrable), <i lang="en">an internship</i> (un stage).</li><li>E-mail formel : <i lang="en">Dear Ms Bennett → Yours sincerely</i> ; <i lang="en">Dear Sir or Madam → Yours faithfully</i>. <i lang="en">I am writing to…, Please find attached…, I would be grateful if you could…, I look forward to hearing from you.</i> Pas de contractions.</li><li>Prononciation : <i lang="en">have to /hæftə/, has to /hæstə/, mustn’t /mʌsnt/</i>.</li></ul></div>`},

 {kind:'Mission', h:'A call from HR',
  p:'You applied for the events assistant job. Now Laura Bennett, the HR manager, is calling you. Listen to the conversation, then answer the questions one by one. You can listen again at any time.',
  audio:[['Laura','Hello, is that Camille Favre? It’s Laura Bennett from the Harbour View Hotel.'],['Camille','Oh, hello! Yes, speaking.'],['Laura','I’m calling about your application. We were very impressed, and we’d like to invite you to a second interview next Thursday at eleven.'],['Camille','That’s great news, thank you! Is there anything I need to prepare?'],['Laura','Yes. You’ll have to give a short presentation, about ten minutes, on how you would organise a wedding for a hundred guests. You don’t have to bring a laptop: we’ll have one ready for you.'],['Camille','Perfect. Will I meet the events manager?'],['Laura','Yes, Mr Shaw will be there. Oh, and you must bring your passport, because we have to check that you’re allowed to work in the UK.'],['Camille','Of course. Thank you so much.']], cache:true,
  parts:[
   {q:'a) When is the second interview?', opts:['Next Tuesday at 11','Next Thursday at 11','Next Thursday at 10','This Thursday at 1'], ans:1, hint:'Listen for the day, then for the time just after it.', why:'<i lang="en">A second interview next Thursday at eleven</i> : jeudi prochain à 11 heures.'},
   {q:'b) Complete Camille’s notes: <i lang="en">I ___ bring a laptop: they will have one ready.</i>', lab:'Missing words', txt:['do not have to','do not need to','need not'], hint:'It is not forbidden, it is just not necessary.', why:'<i lang="en">You don’t have to bring a laptop</i> : pas nécessaire (et pas interdit). « mustn’t » serait faux.'},
   {q:'c) Why must Camille bring her passport?', opts:['To book a hotel room','Because the hotel has to check that she can work in the UK','Because Mr Shaw wants to see it','To travel to the hotel'], ans:1, hint:'Listen for <i lang="en">because</i> after <i lang="en">passport</i>.', why:'<i lang="en">We have to check that you’re allowed to work in the UK</i> : l’hôtel doit vérifier son droit de travailler au Royaume-Uni.'},
   {q:'d) After the call, Camille is happy. Complete her deduction (she is almost sure): <i lang="en">They ___ interested in my profile!</i>', lab:'Missing words', txt:['must be','must really be','must be really'], hint:'Almost sure it is true: modal + <i lang="en">be</i>.', why:'<i lang="en">They must be interested in my profile!</i> Ils l’ont dit (<i lang="en">we were very impressed</i>) : déduction presque certaine → <i lang="en">must be</i>.'}],
  sol:'<p lang="en">Second interview: next Thursday at 11 am with Laura Bennett and Mr Shaw. I have to give a ten-minute presentation on how I would organise a wedding for 100 guests. I don’t have to bring a laptop, but I must bring my passport, because they have to check that I am allowed to work in the UK.</p><p>Les obligations sont exprimées avec <i lang="en">have to</i> et <i lang="en">must</i>, l’absence d’obligation avec <i lang="en">don’t have to</i>, et Camille fait une déduction avec <i lang="en">must be</i>.</p>'},

 {kind:'Mission', h:'Your first week',
  p:`<p>You got the job! Before your first day, you receive this email from your new manager. Read it, then answer.</p>
<div class="blk" data-t="From: Richard Shaw · Subject: Your first week"><p lang="en">Dear Camille,</p><p lang="en">Welcome to the events team! Here are a few things you need to know before Monday.</p><p lang="en">You must wear your staff badge at all times in the hotel. You don’t have to wear a uniform in the office, but you will have to wear the black suit we will give you during events.</p><p lang="en">For safety reasons, staff mustn’t use the guest lift when they are carrying equipment. Please use the service lift next to the kitchen.</p><p lang="en">On Monday, you won’t need to bring lunch: the whole team is invited to a welcome lunch at 1 pm.</p><p lang="en">Finally, could you complete the attached form and send it back to me by Friday? I need it to set up your email account.</p><p lang="en">Best regards,<br>Richard Shaw, Events Manager</p></div>`,
  parts:[
   {q:'a) Which of these is forbidden?', opts:['Wearing a uniform in the office','Using the guest lift while carrying equipment','Bringing lunch on Monday','Using the service lift'], ans:1, hint:'Look for <i lang="en">mustn’t</i>.', why:'<i lang="en">Staff mustn’t use the guest lift when they are carrying equipment</i> : c’est interdit. Le reste n’est pas obligatoire ou est même conseillé.'},
   {q:'b) A friend asks: <i lang="en">Do you have to wear a uniform in the office?</i> Answer in a full sentence.', lab:'Your answer', txt:[...X(['No,','No'],['I do not have to','I do not need to','I need not'],['wear a uniform in the office','wear one in the office','wear a uniform','wear one']),'No, I do not.','No, I do not have to.','No, I do not need to.'], hint:'Not necessary: <i lang="en">No, I don’t…</i>', why:'<i lang="en">No, I don’t have to wear a uniform in the office.</i> En revanche, il faudra porter un costume noir pendant les événements (<i lang="en">I will have to wear a black suit</i>).'},
   {q:'c) On Monday at 9 am, you see a man in a black suit pushing chairs into the service lift. Translate your deduction: « Il doit faire partie de l’équipe des événements. »', lab:'Your sentence', txt:X('He must be',['part of the events team','in the events team','on the events team','a member of the events team','one of the events team']), hint:'Almost sure: <i lang="en">He must be</i>…', why:'<i lang="en">He must be part of the events team.</i> Costume noir et matériel dans le monte-charge : déduction presque certaine.'},
   {q:'d) You reply formally and send the form. Translate: « Veuillez trouver ci-joint le formulaire. »', lab:'Your sentence', txt:[...X('Please find attached',['the form','the completed form']),'Please find the form attached.','Please find the completed form attached.','I have attached the form.','I attach the form.','I am attaching the form.','The form is attached.'], hint:'It is one of the formal email chunks: <i lang="en">Please find…</i>', why:'<i lang="en">Please find attached the form.</i> (ou <i lang="en">Please find the form attached.</i>) C’est la formule standard pour une pièce jointe.'}],
  sol:'<p>Ce qui est obligatoire : porter son badge (<i lang="en">must</i>), porter le costume noir pendant les événements (<i lang="en">will have to</i>), renvoyer le formulaire avant vendredi. Ce qui est interdit : prendre l’ascenseur des clients avec du matériel (<i lang="en">mustn’t</i>). Ce qui n’est pas nécessaire : l’uniforme au bureau (<i lang="en">don’t have to</i>), le repas de lundi (<i lang="en">won’t need to</i>). Pour la déduction, <i lang="en">He must be part of the events team</i>. Pour la réponse : <i lang="en">Dear Richard, Thank you for your email. Please find attached the completed form. I look forward to meeting the team on Monday. Kind regards, Camille.</i></p>'},
]},
);
})();
